insert into public.topics (id, subject_id, slug, title, priority, marks_hint, content, viva, vignette, tags) overriding system value values
(1, 1, 'ameloblastoma', 'Ameloblastoma', 'must_know', '10-mark essay', '{"definition":"A benign but locally aggressive epithelial odontogenic tumour arising from remnants of the dental lamina, the enamel organ, the lining of odontogenic cysts or the basal cells of the oral mucosa. It is the most common clinically significant odontogenic tumour.","classification":["WHO 2022: Conventional, Unicystic, Peripheral (extraosseous), Metastasizing ameloblastoma; Adenoid ameloblastoma (new entity)","Histological patterns: Follicular (most common), Plexiform, Acanthomatous, Granular cell, Basal cell, Desmoplastic","Unicystic subtypes (Ackermann): Luminal, Intraluminal (plexiform), Mural"],"clinical_features":["Peak in the 3rd–5th decade; unicystic type is seen in younger patients (2nd–3rd decade)","About 80% occur in the mandible, mostly in the molar–ramus region","Painless, slow-growing swelling with expansion of the cortical plates; egg-shell crackling","Tooth mobility and displacement; paraesthesia is rare"],"investigations":["OPG / CBCT: multilocular \"soap-bubble\" (large loculi) or \"honeycomb\" (small loculi) radiolucency","Knife-edge root resorption of adjacent teeth; cortical thinning and expansion","Desmoplastic type: mixed radiolucent–radiopaque lesion, often in the anterior maxilla, mimicking a fibro-osseous lesion","Incisional biopsy for diagnosis; BRAF V600E mutation is common in mandibular tumours"],"histopathology":["Follicles or islands of odontogenic epithelium in a fibrous stroma","Peripheral tall columnar ameloblast-like cells showing palisading and reverse polarity of nuclei","Central loosely arranged stellate reticulum-like cells, often with cystic degeneration","Vickers–Gorlin criteria: hyperchromatic basal nuclei, reverse polarity, subnuclear cytoplasmic vacuolation"],"management":["Conventional: segmental or marginal resection with 1–1.5 cm bony margins","Reconstruction, e.g. with a vascularised fibula free flap or a non-vascularised iliac graft","Unicystic (luminal/intraluminal): enucleation with Carnoy''s solution or peripheral ostectomy; mural type is treated like the conventional tumour","Long-term follow-up: recurrence after simple curettage of conventional ameloblastoma is very high (50–90%)"],"viva_pearls":["Most common pattern: follicular. The histological pattern does not change behaviour – prognosis depends on the clinical type (conventional vs unicystic vs peripheral).","Desmoplastic ameloblastoma is the exception: anterior maxilla, mixed density, mimics a fibro-osseous lesion.","Ameloblastic carcinoma ≠ metastasizing ameloblastoma: the latter is histologically benign yet metastasises (usually to the lung)."]}'::jsonb, '[{"q":"Define ameloblastoma.","keywords":["benign","locally aggressive|locally invasive|aggressive","odontogenic","epithelial|epithelium","tumour|tumor|neoplasm"],"probe":"Is it benign or malignant, and how does it behave locally?"},{"q":"Describe its radiographic appearance.","keywords":["multilocular","soap bubble|soap-bubble|honeycomb","radiolucen","root resorption|knife edge|knife-edge|resorption","expansion|cortical"],"probe":"Tell me about the locularity, and what happens to the roots of adjacent teeth."},{"q":"Describe the histopathology of the follicular type.","keywords":["follicle|islands","columnar","reverse polarity|reversed polarity","stellate reticulum","palisad"],"probe":"What are the Vickers–Gorlin criteria?"},{"q":"How will you manage a conventional ameloblastoma of the mandible?","keywords":["resection","margin|1 cm|1.5 cm|safe margin","reconstruct|fibula|graft","recurrence|follow"],"probe":"Why is curettage alone not acceptable for the conventional type?"}]'::jsonb, 'A 35-year-old man has a painless, slowly enlarging swelling of the right posterior mandible over 2 years. There is buccal and lingual cortical expansion with egg-shell crackling. The OPG shows a multilocular radiolucency in the molar–ramus region with resorption of the adjacent molar roots.', array['odontogenic tumour','multilocular']::text[]),
(2, 1, 'odontogenic-keratocyst', 'Odontogenic Keratocyst (OKC)', 'must_know', '10-mark essay', '{"definition":"A developmental odontogenic cyst arising from remnants of the dental lamina, lined by a thin, uniform parakeratinised stratified squamous epithelium. It is known for its aggressive growth and high recurrence. (WHO 2005 called it keratocystic odontogenic tumour; WHO 2017/2022 re-classified it as a cyst.)","classification":["Solitary (sporadic)","Multiple – associated with Gorlin–Goltz (nevoid basal cell carcinoma) syndrome","Orthokeratinised odontogenic cyst is now a separate, less aggressive entity"],"clinical_features":["2nd–4th decade; male predilection","Mandible (about 70%), especially the posterior body and ramus","Grows antero-posteriorly through medullary bone, so expansion is minimal until late","Often asymptomatic; may present with pain, swelling or discharge if infected"],"investigations":["Radiograph: unilocular or multilocular radiolucency with smooth, scalloped, corticated borders","Aspirate: low soluble protein (< 4 g/dL) with keratin squames","Biopsy is diagnostic; PTCH1 gene mutation is seen in syndromic and many sporadic cases"],"histopathology":["Uniform parakeratinised stratified squamous epithelium, 6–8 cell layers thick","Corrugated (wavy) parakeratin surface","Palisaded, hyperchromatic basal cells – \"tombstone\" appearance","Flat epithelium–connective tissue interface; satellite (daughter) cysts in the fibrous wall"],"management":["Enucleation with peripheral ostectomy and/or Carnoy''s solution (modified Carnoy''s without chloroform)","Decompression or marsupialisation for large lesions, followed by enucleation","Excise the overlying attached mucosa if it is adherent","Long-term follow-up (at least 5–10 years); recurrence is about 25–60% after simple enucleation"],"viva_pearls":["Why does it recur? Thin, friable lining; satellite cysts; residual dental lamina rests; high mitotic activity of the epithelium.","Gorlin–Goltz: multiple OKCs, multiple basal cell carcinomas, bifid ribs, calcified falx cerebri, palmar/plantar pits."]}'::jsonb, '[{"q":"What is an odontogenic keratocyst?","keywords":["developmental","odontogenic","dental lamina","parakeratin","recurrence|aggressive|recur"],"probe":"What is its origin, and what kind of keratin lines it?"},{"q":"Describe the histopathology.","keywords":["corrugated|wavy","parakeratin","palisad|tombstone","uniform|6|8 cell","satellite|daughter"],"probe":"Describe the basal cell layer and the surface keratin."},{"q":"Why does an OKC recur so often?","keywords":["thin|friable","satellite|daughter","dental lamina|rests","mitotic|proliferat"],"probe":"Think about the lining and what is left behind in the cyst wall."},{"q":"Which syndrome is associated with multiple OKCs? List its features.","keywords":["gorlin|nevoid basal cell","basal cell carcinoma","bifid rib","falx|calcification","ptch|pits"],"probe":"Name the skin malignancy and the skeletal anomaly in this syndrome."},{"q":"How do you manage it?","keywords":["enucleation","carnoy","ostectomy|peripheral ostectomy","marsupial|decompression","follow"],"probe":"What adjunct do you use to reduce recurrence?"}]'::jsonb, 'A 24-year-old man has a vague swelling of the left ramus. The OPG shows a large radiolucency with scalloped, corticated margins extending along the body of the mandible, with very little bony expansion. Aspiration yields thick, cheesy, creamy material.', array['developmental cyst','Gorlin']::text[]),
(3, 1, 'radicular-cyst', 'Radicular (Periapical) Cyst', 'must_know', '5-mark short note', '{"definition":"An inflammatory odontogenic cyst arising from the epithelial cell rests of Malassez in the periodontal ligament, following periapical inflammation caused by a non-vital tooth. It is the most common odontogenic cyst.","classification":["Periapical (apical) radicular cyst","Lateral radicular cyst (from a lateral/accessory canal)","Residual cyst (remains after the tooth is extracted)"],"etiology":["Pulp necrosis → periapical granuloma → proliferation of the rests of Malassez","Phases: initiation, cyst formation, enlargement","Enlargement by osmotic / hydrostatic pressure and bone resorption by prostaglandins"],"clinical_features":["3rd–6th decade; most common in the maxillary anterior region","Always associated with a non-vital tooth","Usually asymptomatic; slow expansion; may become infected"],"investigations":["Pulp vitality test: non-vital","Well-defined round or ovoid radiolucency at the apex with a corticated border and loss of lamina dura","Cannot be reliably differentiated from a periapical granuloma on radiographs – histology confirms"],"histopathology":["Non-keratinised stratified squamous epithelium of variable thickness, with arcading","Rushton (hyaline) bodies in the epithelium","Cholesterol clefts, foam cells and chronic inflammatory cells in the capsule"],"management":["Root canal treatment – small lesions often heal","Periapical surgery (apicectomy with enucleation and retrograde filling) for persistent lesions","Extraction with curettage if the tooth is non-restorable; marsupialisation for very large cysts"],"viva_pearls":["Tooth must be non-vital – a vital tooth with an apical radiolucency points to another diagnosis.","Rushton bodies are seen in radicular and dentigerous cysts."]}'::jsonb, '[{"q":"Define a radicular cyst.","keywords":["inflammatory","malassez","non vital|non-vital|necrotic|nonvital","periapical|apex|apical"],"probe":"From which epithelial rests does it arise?"},{"q":"Explain its pathogenesis.","keywords":["initiation","proliferat|formation","enlargement|osmotic|hydrostatic","granuloma"],"probe":"What are the three phases?"},{"q":"Describe the histopathology.","keywords":["non keratin|non-keratin|nonkeratin","rushton|hyaline","cholesterol","arcad","inflammat"],"probe":"Which bodies are seen in the lining?"},{"q":"How will you treat it?","keywords":["root canal|rct|endodontic","apicectomy|apicoectomy|periapical surgery","enucleation","extraction|marsupial"],"probe":"Can a small radicular cyst heal without surgery?"}]'::jsonb, 'A 32-year-old woman has a discoloured, non-vital maxillary left central incisor that was traumatised years ago. An IOPA radiograph shows a well-defined, round, corticated radiolucency about 1.5 cm across at the apex.', array['inflammatory cyst']::text[]),
(4, 2, 'osmf', 'Oral Submucous Fibrosis', 'must_know', '10-mark essay', '{"definition":"A chronic, insidious, progressive, potentially malignant disorder of the oral mucosa, characterised by juxta-epithelial inflammation and progressive fibrosis of the submucosa, leading to stiffness and restricted mouth opening (Pindborg & Sirsat, 1966).","etiology":["Areca nut – arecoline stimulates fibroblasts; tannins/flavonoids inhibit collagenase; high copper increases lysyl oxidase activity","Chillies (capsaicin) – controversial","Nutritional deficiency – iron, vitamin B complex","Genetic and immunological factors (HLA associations)"],"classification":["Khanna & Andrade (surgical grouping): I very early; II early (opening 26–35 mm); III moderately advanced (15–26 mm); IVa advanced (< 15 mm, extensive fibrosis); IVb advanced with premalignant/malignant change"],"clinical_features":["Earliest symptom: burning sensation with spicy food; vesicles","Blanching (marble-like) of the mucosa; palpable vertical fibrous bands","Progressive restriction of mouth opening; difficulty in eating and speech","Shrunken, bud-like or hockey-stick uvula; depapillated tongue; hearing loss from Eustachian tube involvement"],"investigations":["Measure interincisal distance at every visit","Incisional biopsy to look for dysplasia","Haemoglobin, serum iron, B12"],"histopathology":["Atrophic epithelium with loss of rete ridges","Juxta-epithelial hyalinisation; dense collagen with reduced vascularity","Chronic inflammatory infiltrate; epithelial dysplasia in some cases"],"management":["Stop the habit – the single most important step","Nutritional and antioxidant supplements (lycopene, vitamins, iron)","Intralesional injections – dexamethasone or triamcinolone with hyaluronidase; pentoxifylline orally","Physiotherapy – mouth-opening exercises (ice-cream sticks, Heister''s jaw opener)","Surgery for advanced cases – fibrotomy with buccal pad of fat or nasolabial flap reconstruction","Lifelong follow-up for malignant transformation (reported around 7–13%)"],"viva_pearls":["Arecoline → fibroblast proliferation; copper → lysyl oxidase → collagen cross-linking.","OSMF is irreversible – treatment halts progression and improves opening, it does not cure."]}'::jsonb, '[{"q":"Define oral submucous fibrosis.","keywords":["chronic","progressive|insidious","fibrosis","submucosa|submucosal","potentially malignant|premalignant|precancer"],"probe":"Is it reversible, and is it a potentially malignant disorder?"},{"q":"What is its aetiology?","keywords":["areca|arecoline|betel","copper","chilli|capsaicin","nutrition|iron|vitamin","genetic|immun|hla"],"probe":"What is the role of copper in areca nut?"},{"q":"What are the clinical features?","keywords":["burning","blanch|marble","fibrous band|bands","mouth opening|trismus","uvula"],"probe":"What is usually the earliest complaint?"},{"q":"How will you manage this patient?","keywords":["stop|cessation|quit|habit","intralesional","hyaluronidase","steroid|dexamethasone|triamcinolone","physiotherapy|exercise","surgery|fibrotomy|buccal fat|buccal pad"],"probe":"Which drugs are given intralesionally, and what do you advise for mouth opening?"}]'::jsonb, 'A 28-year-old man who has chewed gutka for 8 years complains of a burning sensation with spicy food and gradually increasing difficulty opening his mouth. The interincisal opening is 22 mm, with palpable vertical fibrous bands in both buccal mucosae and a blanched soft palate.', array['OPMD','areca nut']::text[]),
(5, 2, 'leukoplakia', 'Oral Leukoplakia', 'must_know', '10-mark essay', '{"definition":"A predominantly white plaque of questionable risk, having excluded other known diseases or disorders that carry no increased risk for cancer (WHO / Warnakulasuriya 2007). It is a clinical, not a histological, term.","classification":["Homogeneous – uniformly flat, thin, white","Non-homogeneous – speckled (erythroleukoplakia), nodular, verrucous","Proliferative verrucous leukoplakia (PVL) – multifocal, highest malignant potential","OLEP staging uses size (L1–L3) and pathology (P0, P1)"],"etiology":["Tobacco (smoked and smokeless) – most important","Alcohol","Candida albicans (candidal leukoplakia)","Sanguinaria, UV light (lip), idiopathic"],"clinical_features":["Middle-aged and elderly men; buccal mucosa and commissure are most common in India","High-risk sites: floor of mouth, ventral/lateral tongue, soft palate","Usually asymptomatic; speckled forms may be sore"],"investigations":["Remove irritants and review in 2–4 weeks","Toluidine blue staining to select the biopsy site","Incisional biopsy from the most suspicious (red/nodular) area","Exfoliative / brush cytology as an adjunct"],"histopathology":["Hyperkeratosis (ortho- or para-), acanthosis","With or without epithelial dysplasia, graded mild / moderate / severe","Carcinoma in situ or early invasion in some"],"management":["Stop tobacco and alcohol","No dysplasia: monitor; medical therapy (retinoids, lycopene, beta-carotene) has limited evidence","Dysplasia: surgical excision, CO2 laser ablation or cryotherapy","Long-term follow-up – recurrence and new lesions are common"],"viva_pearls":["High-risk features: non-homogeneous type, high-risk site, dysplasia, female non-smoker, size > 200 mm², candidal infection, long duration.","Erythroplakia carries a much higher malignant potential than leukoplakia."]}'::jsonb, '[{"q":"Define leukoplakia.","keywords":["white","plaque|patch","questionable risk|risk","exclud|exclusion"],"probe":"Is it a clinical or a histological diagnosis? What must be excluded first?"},{"q":"Classify leukoplakia.","keywords":["homogeneous","non homogeneous|non-homogeneous|nonhomogeneous","speckled|erythroleukoplakia","nodular","verrucous|proliferative"],"probe":"What are the subtypes of the non-homogeneous form?"},{"q":"Which features suggest a higher risk of malignant transformation?","keywords":["non homogeneous|non-homogeneous|speckled","floor of mouth|ventral|tongue","dysplasia","female|non smoker|non-smoker","size|candida|duration"],"probe":"Think about type, site, histology and the patient."},{"q":"How will you manage this patient?","keywords":["tobacco|habit|cessation|stop","biopsy","excision|laser|cryo","follow|review"],"probe":"From where will you take the biopsy?"}]'::jsonb, 'A 55-year-old bidi smoker has a 2 × 3 cm white, slightly fissured patch on the left buccal mucosa near the commissure. It does not rub off and has a small red, granular area at one margin.', array['OPMD','tobacco']::text[]),
(6, 2, 'oral-lichen-planus', 'Oral Lichen Planus', 'must_know', '5-mark short note', '{"definition":"A chronic, T-cell–mediated immunological mucocutaneous disease affecting stratified squamous epithelium. WHO lists it as an oral potentially malignant disorder.","classification":["Reticular (most common – Wickham''s striae)","Papular","Plaque-like","Atrophic","Erosive / ulcerative","Bullous"],"clinical_features":["Middle-aged women","Bilateral, symmetrical lesions – buccal mucosa most common; tongue and gingiva (desquamative gingivitis)","Skin: 6 Ps – pruritic, purple, polygonal, planar papules and plaques; Koebner phenomenon","Erosive form causes burning and pain"],"investigations":["Incisional biopsy","Direct immunofluorescence – shaggy fibrinogen at the basement membrane","Rule out lichenoid reactions (drugs, amalgam contact)"],"histopathology":["Hyperkeratosis (parakeratosis) with saw-tooth rete ridges","Liquefaction (hydropic) degeneration of the basal cell layer","Dense band-like subepithelial lymphocytic infiltrate","Civatte (colloid) bodies; Max-Joseph spaces"],"management":["Asymptomatic reticular: reassurance and review","Symptomatic: topical corticosteroids (clobetasol, triamcinolone in orabase), topical tacrolimus","Severe / recalcitrant: systemic corticosteroids","Treat secondary candidiasis; replace amalgam in lichenoid reactions; follow up long term"],"viva_pearls":["Wickham''s striae = reticular OLP.","Civatte bodies are apoptotic keratinocytes."]}'::jsonb, '[{"q":"Define lichen planus.","keywords":["chronic","immun|t cell|t-cell","mucocutaneous"],"probe":"What type of immune mechanism is involved?"},{"q":"What are the oral clinical forms and features?","keywords":["wickham","reticular","erosive","bilateral|symmetrical","buccal mucosa"],"probe":"What are the striae called, and which is the most common type?"},{"q":"Describe the histopathology.","keywords":["saw tooth|saw-tooth","band like|band-like|band","lymphocyt","civatte|colloid","liquefaction|hydropic|basal"],"probe":"What happens to the basal cell layer?"},{"q":"How will you treat erosive lichen planus?","keywords":["corticosteroid|steroid","clobetasol|triamcinolone","tacrolimus","follow|review"],"probe":"Which topical agents would you prescribe?"}]'::jsonb, 'A 45-year-old woman has bilateral lace-like white striae on both buccal mucosae, with an erosive, painful area on the right side. She also has itchy purple papules on her wrists.', array['OPMD','immune-mediated']::text[]),
(7, 3, 'impacted-third-molar', 'Impacted Mandibular Third Molar', 'must_know', '10-mark essay', '{"definition":"An impacted tooth is one that fails to erupt into its normal functional position within the expected time because of an obstruction (adjacent tooth, bone or soft tissue) or an abnormal path of eruption.","classification":["Winter''s (angulation): mesioangular (most common), vertical, distoangular, horizontal, buccoangular, linguoangular, inverted","Pell & Gregory – relation to ramus: Class I, II, III","Pell & Gregory – depth relative to the occlusal plane: Position A, B, C","Winter''s WAR lines (White, Amber, Red) to judge depth and difficulty"],"clinical_features":["Recurrent pericoronitis (most common indication)","Caries or resorption of the second molar","Cyst or tumour formation","Orthodontic / prosthetic reasons; unexplained pain"],"investigations":["OPG / IOPA; CBCT if the roots are close to the inferior alveolar canal","Rood & Shehab signs (roots): darkening, deflection, narrowing, dark and bifid apex","Rood & Shehab signs (canal): interruption of the white lines, diversion, narrowing","Pederson difficulty index"],"management":["Ward''s or modified Ward''s incision, raise a mucoperiosteal flap","Bone removal (buccal guttering) and odontectomy – sectioning the crown or roots","Elevation, debridement, irrigation and closure","Coronectomy when the roots are intimately related to the IAN"],"viva_pearls":["Complications: dry socket, IAN / lingual nerve paraesthesia, trismus, bleeding, damage to adjacent tooth, mandibular fracture.","Most common impaction: mesioangular; most difficult: distoangular."]}'::jsonb, '[{"q":"How do you classify impacted mandibular third molars?","keywords":["winter","pell|gregory","mesioangular|angulation","ramus|occlusal plane|depth"],"probe":"Which classification uses the ramus and the occlusal plane?"},{"q":"What are Winter''s WAR lines?","keywords":["white","amber","red"],"probe":"Name the three lines and what each tells you."},{"q":"Which radiographic signs suggest proximity to the inferior alveolar canal?","keywords":["rood|shehab","darkening","deflection","narrowing","interruption|white line|diversion"],"probe":"List the root signs and the canal signs."},{"q":"What complications would you warn the patient about?","keywords":["dry socket|alveolar osteitis","paraesthesia|paresthesia|nerve|numbness","trismus","bleeding|haemorrhage|hemorrhage","fracture|swelling"],"probe":"Which nerves are at risk?"}]'::jsonb, 'A 22-year-old woman has recurrent pain and swelling around her lower right third molar region. The OPG shows a mesioangular impacted 48 at the level of the occlusal plane, partly within the ramus, with its roots overlapping the inferior alveolar canal.', array['exodontia','Winter','Pell & Gregory']::text[]),
(8, 3, 'le-fort-fractures', 'Le Fort Fractures of the Maxilla', 'must_know', '10-mark essay', '{"definition":"René Le Fort (1901) classified midface fractures from cadaver experiments into three patterns along lines of weakness. All three involve the pterygoid plates.","classification":["Le Fort I (Guérin / horizontal): above the apices – floor of nose, lateral maxillary walls, lower pterygoid plates; \"floating palate\"","Le Fort II (pyramidal): nasal bones, frontal process of maxilla, medial orbital wall, orbital floor, infraorbital margin, zygomaticomaxillary region, pterygoid plates","Le Fort III (craniofacial dysjunction): frontonasal and frontozygomatic sutures, orbital floor, zygomatic arch, pterygoid plates"],"clinical_features":["Guérin''s sign – ecchymosis at the greater palatine foramen (Le Fort I)","Anterior open bite with premature posterior contact; mobility of the maxilla","Dish-face deformity and lengthening of the face (II, III)","Circumorbital ecchymosis (\"raccoon eyes\"), step at the infraorbital margin (II), CSF rhinorrhoea (II, III)"],"investigations":["CT scan with axial, coronal and 3-D reconstruction (gold standard)","Occipitomental (Waters) view","Beta-2 transferrin test for CSF leak"],"management":["ATLS: airway, breathing, circulation, cervical spine first","Disimpaction with Rowe''s forceps; restore occlusion with intermaxillary fixation","Open reduction and internal fixation with miniplates along the vertical buttresses (nasomaxillary, zygomaticomaxillary, pterygomaxillary)","Manage CSF leak conservatively (head elevation, avoid nose blowing)"],"viva_pearls":["All Le Fort fractures involve the pterygoid plates.","CSF rhinorrhoea → avoid nasal intubation and nasogastric tubes."]}'::jsonb, '[{"q":"Classify Le Fort fractures.","keywords":["le fort i|guerin|guérin|horizontal","pyramidal","craniofacial dysjunction|dysjunction","pterygoid"],"probe":"Which structure is involved in all three types?"},{"q":"What clinical signs would you look for?","keywords":["guerin|guérin","open bite","dish face|dish-face","raccoon|circumorbital|periorbital","csf|rhinorrh","step"],"probe":"What is Guérin''s sign?"},{"q":"Which investigations will you order?","keywords":["ct|computed tomography","water|occipitomental","beta 2 transferrin|beta-2|transferrin"],"probe":"How would you confirm a CSF leak?"},{"q":"Outline the management.","keywords":["airway|abc|atls","occlusion|imf|mmf|intermaxillary","orif|miniplate|plate","buttress","rowe|disimpaction"],"probe":"Along which buttresses are plates placed?"}]'::jsonb, 'A 30-year-old man after a road traffic accident has bilateral circumorbital ecchymosis, an elongated "dish face", an anterior open bite and clear fluid dripping from the nose. The whole midface moves when the anterior maxilla is rocked.', array['trauma','midface']::text[]),
(9, 4, 'mta', 'Mineral Trioxide Aggregate (MTA)', 'must_know', '5-mark short note', '{"definition":"A hydrophilic calcium silicate–based cement developed by Mahmoud Torabinejad at Loma Linda University (1993), which sets in the presence of moisture and is highly biocompatible.","classification":["Grey MTA","White MTA (less iron, less discolouration)","Newer calcium silicates: Biodentine, BioAggregate, EndoSequence bioceramics"],"clinical_features":["Composition: tricalcium silicate, dicalcium silicate, tricalcium aluminate, tetracalcium aluminoferrite, calcium sulphate (gypsum), bismuth oxide (radiopacifier)","Mixed with sterile water in a 3:1 powder : liquid ratio","pH 10.2 on mixing, rising to about 12.5 at 3 hours","Setting time about 2 h 45 min (165 min); compressive strength increases over days"],"investigations":["Mechanism: hydration releases calcium hydroxide → Ca²⁺ and OH⁻ release, hydroxyapatite-like layer at the dentine interface, induction of cementum and dentine bridge"],"management":["Uses: direct pulp capping, pulpotomy, apexification (apical plug), root-end filling, perforation repair (furcal/lateral), resorption repair, regenerative endodontics barrier","Advantages: excellent seal, biocompatibility, sets in moisture, antibacterial (high pH), induces hard tissue","Disadvantages: long setting time, tooth discolouration (bismuth oxide), difficult handling, cost"],"viva_pearls":["Biodentine sets in about 12 minutes – a key advantage over MTA.","Place a moist cotton pellet over MTA when it is used in a single sitting under a temporary seal."]}'::jsonb, '[{"q":"What is MTA?","keywords":["calcium silicate|tricalcium silicate|silicate","torabinejad","hydrophilic|moisture"],"probe":"Who introduced it, and how does it behave with moisture?"},{"q":"What is its composition?","keywords":["tricalcium silicate","dicalcium silicate","aluminate","bismuth oxide","gypsum|calcium sulphate|calcium sulfate"],"probe":"What provides its radiopacity?"},{"q":"What are its important properties?","keywords":["ph|12.5","setting time|165|2 hours|2 h","biocompatib","seal","antibacterial|hard tissue"],"probe":"What are its pH and setting time?"},{"q":"List its clinical uses.","keywords":["perforation","apexification|apical plug","pulp capping","root end|root-end|retrograde","pulpotomy"],"probe":"Would you use it for perforation repair? What else?"}]'::jsonb, 'During access opening of tooth 36, a furcal perforation of about 1.5 mm is created. Bleeding is controlled. You decide to repair it in the same visit.', array['bioceramic','endodontics']::text[]),
(10, 5, 'gingival-enlargement', 'Drug-Induced Gingival Enlargement', 'desirable', '5-mark short note', '{"definition":"An increase in the size of the gingiva caused by certain systemic drugs, made worse by plaque-induced inflammation. \"Enlargement\" is preferred over hyperplasia or hypertrophy.","classification":["Carranza: inflammatory, drug-induced, associated with systemic conditions (conditioned or systemic disease), neoplastic, false enlargement","Grading: 0 – none; I – confined to interdental papilla; II – papilla and marginal gingiva; III – covering three-quarters or more of the crown"],"etiology":["Anticonvulsants – phenytoin (about half of patients), valproate","Immunosuppressants – cyclosporine","Calcium-channel blockers – nifedipine, amlodipine, diltiazem, verapamil"],"clinical_features":["Begins as painless, bead-like enlargement of the interdental papilla","Firm, pink, lobulated; does not bleed easily unless inflamed","More common anteriorly and on the labial surface; may interfere with speech and aesthetics"],"investigations":["Detailed drug history; consult the physician","Biopsy if the appearance is atypical"],"management":["Professional scaling and meticulous plaque control","Ask the physician to substitute the drug (e.g. tacrolimus for cyclosporine, another antihypertensive)","Azithromycin may help cyclosporine-induced enlargement","Surgical: gingivectomy (external bevel) or flap surgery; laser; recurrence is common if the drug continues"],"viva_pearls":["Mechanism: increased fibroblast collagen synthesis, reduced collagenase activity, reduced folic acid uptake (phenytoin); inflammation is a co-factor."]}'::jsonb, '[{"q":"Classify gingival enlargement.","keywords":["inflammatory","drug","systemic|conditioned","neoplastic","false"],"probe":"Give me Carranza''s classification."},{"q":"Name the drugs that cause it.","keywords":["phenytoin","cyclosporin","nifedipine|calcium channel","amlodipine|diltiazem|verapamil"],"probe":"Which three drug groups are classically implicated?"},{"q":"What is the mechanism?","keywords":["fibroblast","collagen","folic|folate","inflammation|plaque","collagenase"],"probe":"What is the role of plaque?"},{"q":"How will you manage it?","keywords":["plaque control|scaling|oral hygiene","substitut|change|physician","gingivectomy|flap","azithromycin|laser"],"probe":"Whom will you consult before stopping the drug?"}]'::jsonb, 'A 50-year-old hypertensive man on amlodipine has firm, pink, lobulated overgrowth of the interdental papillae covering about a third of the crowns of his anterior teeth. Plaque control is poor.', array['gingiva','drugs']::text[]),
(11, 6, 'kennedy-classification', 'Kennedy Classification & Applegate''s Rules', 'must_know', '5-mark short note', '{"definition":"Edward Kennedy (1925) classified partially edentulous arches by the location of the edentulous spaces relative to the remaining teeth. It is the most widely used classification for removable partial dentures.","classification":["Class I – bilateral edentulous areas posterior to the remaining teeth (bilateral distal extension)","Class II – unilateral edentulous area posterior to the remaining teeth (unilateral distal extension)","Class III – unilateral edentulous area with natural teeth both anterior and posterior to it (bounded)","Class IV – single, bilateral edentulous area anterior to the remaining teeth, crossing the midline","Applegate added Class V and Class VI"],"management":["Applegate''s 8 rules – e.g. classify after extractions; missing third molars not to be replaced are ignored; a third molar used as an abutment is considered","The most posterior edentulous area determines the class; other areas are modification spaces","Only the number of modification spaces counts, not their extent","Class IV has no modification spaces"],"clinical_features":["Class I & II: tooth–tissue supported – need functional impressions, indirect retainers, stress breakers / RPI design","Class III: tooth supported – anatomic impression is adequate"],"viva_pearls":["The question in this vignette (only 33–43 present) is Kennedy Class I."]}'::jsonb, '[{"q":"Describe Kennedy''s classification.","keywords":["bilateral distal|bilateral posterior|class i","unilateral distal|unilateral posterior|class ii","bounded|class iii","anterior|midline|class iv"],"probe":"What defines Class IV?"},{"q":"What are Applegate''s rules?","keywords":["applegate","extraction|after","third molar","most posterior","modification"],"probe":"Which area determines the class?"},{"q":"Which classes are tooth-supported and which are tooth–tissue supported? Why does it matter?","keywords":["tooth supported|tooth-supported|tooth borne","tissue|mucosa","functional impression|impression","indirect retainer|stress breaker|rpi"],"probe":"How does a distal extension change your impression technique?"}]'::jsonb, 'A 60-year-old patient has a mandibular arch with only 33 to 43 remaining and wants a removable partial denture.', array['RPD']::text[]),
(12, 7, 'pulpotomy-primary', 'Pulpotomy in Primary Teeth', 'desirable', '5-mark short note', '{"definition":"Removal of the coronal pulp, leaving the vital radicular pulp, which is treated with a medicament to preserve its vitality and function.","classification":["Devitalisation – formocresol","Preservation – ferric sulphate, glutaraldehyde","Regeneration – MTA, Biodentine, calcium hydroxide","Non-pharmacological – electrosurgery, laser"],"clinical_features":["Indications: carious or mechanical exposure of a vital primary tooth; haemorrhage controlled within about 5 minutes; no radiographic pathology; restorable tooth","Contraindications: spontaneous pain, swelling or sinus, pathological mobility, furcation radiolucency, internal/external resorption, uncontrollable bleeding"],"management":["LA and rubber dam → caries removal → de-roof the pulp chamber","Amputate the coronal pulp with a spoon excavator or large round bur","Haemostasis with a moist cotton pellet","Apply medicament: Buckley''s formocresol (1:5 dilution) for 5 min; ferric sulphate 15.5% for 15 s; or MTA","Zinc oxide eugenol base; final restoration with a stainless steel crown"],"viva_pearls":["Buckley''s formocresol: 19% formaldehyde, 35% cresol, 15% glycerine in water."]}'::jsonb, '[{"q":"Define pulpotomy.","keywords":["coronal pulp","radicular","vital|vitality","medicament"],"probe":"Which part of the pulp is removed and which is preserved?"},{"q":"What are the indications?","keywords":["vital","exposure","bleeding|haemorrhage|hemorrhage|haemostasis","no radiographic|radiograph","restorable"],"probe":"How long may bleeding continue before you abandon pulpotomy?"},{"q":"Name the medicaments used.","keywords":["formocresol","ferric sulphate|ferric sulfate","mta","biodentine","electrosurg|laser|glutaraldehyde"],"probe":"Which medicament acts by haemostasis through protein agglutination?"},{"q":"What is the composition of Buckley''s formocresol?","keywords":["19|formaldehyde","35|cresol","glycerine|glycerin","1:5|one fifth|dilution"],"probe":"Give the percentages."}]'::jsonb, 'A 6-year-old child has a deep carious lesion in 84 with a carious pulp exposure during excavation. There is no spontaneous pain, the bleeding stops with a moist cotton pellet in 3 minutes, and the radiograph shows no furcation involvement.', array['vital pulp therapy']::text[]),
(13, 8, 'dental-amalgam', 'Dental Amalgam', 'desirable', '10-mark essay', '{"definition":"An alloy of mercury with one or more other metals. Dental amalgam alloy is mainly silver and tin, with copper and sometimes zinc.","classification":["Copper content: low copper (< 6%) and high copper (> 6%) – admixed (dispersed) or single-composition (unicompositional)","Particle shape: lathe-cut, spherical, admixed","Zinc content: zinc-containing (> 0.01%) and zinc-free"],"clinical_features":["Low-copper setting: γ (Ag₃Sn) + Hg → γ₁ (Ag₂Hg₃) + γ₂ (Sn₇₋₈Hg) + unreacted γ","γ₂ is the weakest, most corrosion-prone phase","High-copper alloys eliminate γ₂ by forming Cu₆Sn₅ (η phase) – less creep, corrosion and marginal breakdown"],"etiology":["Delayed (secondary) expansion: zinc-containing alloy + moisture contamination during condensation → hydrogen gas → expansion after 3–5 days, pain and protrusion"],"management":["Manipulation: trituration → condensation → carving → burnishing → polishing after 24 hours","Mercury hygiene: well-ventilated surgery, pre-capsulated alloys, no-touch technique, amalgam separators, safe scrap storage","Minamata Convention (2013) – global phase-down of amalgam use"],"viva_pearls":["In this vignette the cause is delayed expansion: zinc + moisture contamination → H₂."]}'::jsonb, '[{"q":"Write the setting reaction of a low-copper amalgam.","keywords":["gamma|γ","gamma 1|γ1|ag2hg3","gamma 2|γ2|sn7|tin mercury","ag3sn"],"probe":"Name the γ, γ₁ and γ₂ phases."},{"q":"How do high-copper alloys improve amalgam?","keywords":["eliminat|no gamma 2|γ2","cu6sn5|eta|η","corrosion","creep|marginal"],"probe":"Which phase do they remove, and what forms instead?"},{"q":"What is delayed expansion?","keywords":["zinc","moisture|contamination|saliva","hydrogen"],"probe":"Which alloy component reacts with moisture?"},{"q":"What mercury-hygiene measures will you follow?","keywords":["ventilat","capsule|precapsulated|encapsulated","separator","minamata|no touch|gloves"],"probe":"What does the Minamata Convention say?"}]'::jsonb, 'A three-month-old Class II amalgam restoration in a patient''s molar is protruding from the cavity and shows surface blisters. The alloy used was a zinc-containing, low-copper lathe-cut alloy, and the field was not isolated.', array['restorative']::text[]),
(14, 9, 'local-anaesthetics', 'Local Anaesthetics', 'must_know', '10-mark essay', '{"definition":"Drugs that, when applied locally, reversibly block nerve conduction in a restricted area of the body without loss of consciousness.","classification":["Esters: cocaine, procaine, chloroprocaine, tetracaine, benzocaine – hydrolysed by plasma pseudocholinesterase","Amides: lignocaine, mepivacaine, prilocaine, bupivacaine, articaine, ropivacaine – metabolised in the liver (articaine also in plasma)"],"clinical_features":["Mechanism: the non-ionised base crosses the nerve membrane; inside, the ionised form blocks voltage-gated Na⁺ channels from the inner side","Frequency- and voltage-dependent block; small, myelinated fibres are blocked first","Order of loss: autonomic → pain → temperature → touch → pressure → motor"],"etiology":["Infection lowers tissue pH → more of the drug is ionised → less crosses the membrane → reduced effect"],"investigations":["Cartridge: lignocaine 2%, adrenaline 1:80,000–1:200,000 (vasoconstrictor), sodium metabisulphite (antioxidant), sodium chloride (isotonicity), water for injection","Maximum dose: lignocaine 4.4 mg/kg plain (max 300 mg); 7 mg/kg with adrenaline (max 500 mg)"],"management":["Toxicity: CNS excitation (circumoral numbness, tinnitus, tremors, convulsions) then depression; CVS depression","Bupivacaine is the most cardiotoxic; prilocaine causes methaemoglobinaemia (o-toluidine)","Treat toxicity: stop injection, airway and oxygen, benzodiazepine for seizures, lipid emulsion for cardiotoxicity"],"viva_pearls":["Quick rule: amides have two \"i\"s in the name (l-i-docaine, bup-i-vacaine).","Lower pKa → faster onset."]}'::jsonb, '[{"q":"Explain the mechanism of action of local anaesthetics.","keywords":["sodium|na+|na channel","channel","voltage","ionised|ionized|unionised|unionized|non ionised|non-ionised|non ionized","inside|intracellular|inner"],"probe":"Which form crosses the membrane and which form blocks the channel?"},{"q":"Classify them, and how are they metabolised?","keywords":["ester","amide","pseudocholinesterase|plasma cholinesterase|plasma","liver|hepatic"],"probe":"Where are amides metabolised?"},{"q":"What is in a lignocaine cartridge?","keywords":["lignocaine|lidocaine","adrenaline|epinephrine","metabisulphite|metabisulfite|bisulphite|bisulfite","sodium chloride","water"],"probe":"What is the role of sodium metabisulphite?"},{"q":"Why does LA fail in infected tissue?","keywords":["acid|ph","ionised|ionized","less|reduced|fail|decrease","pka|base|membrane"],"probe":"Think about tissue pH and the ionised fraction."},{"q":"What are the signs of LA toxicity, and what is the maximum dose here?","keywords":["cns|convulsion|seizure|tinnitus|circumoral","cardio|cvs|arrhythm|depression","methaemoglobin|methemoglobin|prilocaine","7 mg|420|maximum dose|max"],"probe":"Calculate the maximum lignocaine dose with adrenaline for 60 kg."}]'::jsonb, 'You are about to give an inferior alveolar nerve block for a 40-year-old, 60 kg patient with an acute periapical abscess in 46. She asks why her previous injection "did not work" when the tooth was swollen.', array['LA','lignocaine']::text[]),
(15, 10, 'adc-anaphylaxis', 'Anaphylaxis in the Dental Chair', 'must_know', 'ADC practical – medical emergency', '{"definition":"A severe, potentially life-threatening systemic hypersensitivity reaction of rapid onset, with airway, breathing or circulation problems, usually with skin or mucosal changes.","etiology":["Common dental triggers: latex, antibiotics (e.g. penicillins), chlorhexidine, NSAIDs","True allergy to amide local anaesthetics is very rare – reactions are more often vasovagal or adrenaline effects"],"clinical_features":["Skin/mucosa: urticaria, flushing, angioedema of lips, tongue and face","Airway/breathing: hoarse voice, stridor, wheeze, shortness of breath","Circulation: tachycardia, hypotension, pale and floppy (children), collapse","Gastrointestinal: abdominal pain, vomiting"],"management":["Stop treatment and remove the trigger (take out the latex dam)","Call for help and an ambulance (000)","Lay the patient flat – do not let them stand or walk; sit up only if breathing is difficult","Adrenaline 0.01 mg/kg IM (max 0.5 mg; 0.5 mL of 1:1000) into the anterolateral thigh; repeat every 5 minutes if needed","Oxygen; start CPR if unresponsive and not breathing normally","Transfer to hospital for observation (biphasic reactions), document fully, and refer to a clinical immunologist"],"viva_pearls":["Antihistamines do not treat airway swelling or shock – adrenaline first.","Flag latex allergy in the record and plan latex-free care."]}'::jsonb, '[{"q":"What is your diagnosis and why?","keywords":["anaphylaxis","latex","wheeze|bronchospasm|breathing","hypotension|blood pressure|low bp","angioedema|swelling|urticaria"],"probe":"Which systems are involved, and what is the likely trigger?"},{"q":"What are your immediate actions?","keywords":["remove|stop","help|ambulance|000","flat|lie|supine","adrenaline|epinephrine","oxygen"],"probe":"How will you position her, and who will you call?"},{"q":"Give the adrenaline dose, concentration and route.","keywords":["0.5 mg|0.5mg|500 microgram|0.01 mg/kg","1:1000|1 in 1000","intramuscular|im","thigh","repeat|5 minutes|five minutes"],"probe":"Where exactly do you inject it, and when can you repeat it?"},{"q":"What happens after she recovers?","keywords":["hospital|observation|biphasic","document|record","immunolog|allergist|referral","latex free|latex-free|alert"],"probe":"Why must she still go to hospital?"}]'::jsonb, 'A 34-year-old woman becomes flushed and wheezy, with swelling of her lips, 3 minutes after you place a latex rubber dam. Her pulse is 124/min and blood pressure 80/50 mmHg.', array['ADC','medical emergency']::text[]),
(16, 10, 'adc-consent-notification', 'Consent, Material Risk & Mandatory Notification', 'must_know', 'ADC – ethics & law', '{"definition":"Valid consent is voluntary, informed, specific to the procedure, and given by a person with capacity. In Australia, Rogers v Whitaker (1992) requires practitioners to warn of material risks.","classification":["Implied, verbal and written consent","Mature minors can consent when they fully understand the treatment (Gillick principle, adopted in Marion''s case)","Substitute decision-makers for adults without capacity, as set out by state and territory law"],"clinical_features":["Discuss the diagnosis and the proposed treatment","Explain the risks, both common and serious (e.g. inferior alveolar nerve injury causing numbness)","Explain the alternatives, including coronectomy and no treatment","Discuss cost (informed financial consent) and invite questions"],"management":["\"Do whatever you think is best\" is not informed consent – explain, check understanding and give time","Use a professional interpreter where needed rather than family members","Record the discussion, the risks explained and the patient''s decision","The patient can withdraw consent at any time"],"viva_pearls":["Material risk (Rogers v Whitaker): one a reasonable person in the patient''s position would consider significant, or one the practitioner knows this particular patient would.","Mandatory notification to AHPRA covers practising while intoxicated, sexual misconduct, impairment placing the public at substantial risk, and a significant departure from accepted professional standards."]}'::jsonb, '[{"q":"What makes consent valid?","keywords":["voluntary","inform","capacity|competent|competence","specific"],"probe":"Name the four elements."},{"q":"Which case defines material risk in Australia, and what does it say?","keywords":["rogers|whitaker","material","reasonable person|reasonable patient","particular patient|this patient|significance|significant"],"probe":"Is it judged by what other dentists would do, or by the patient?"},{"q":"What will you discuss with this patient before extracting the tooth?","keywords":["nerve|paraesthesia|paresthesia|numbness","alternative|coronectomy|no treatment","cost|fee|financial","benefit|reason","question|understand"],"probe":"What are her options besides extraction?"},{"q":"When must a dentist make a mandatory notification, and to whom?","keywords":["ahpra","intoxicat|alcohol|drug","sexual","impairment","departure|professional standards"],"probe":"List the four types of notifiable conduct."}]'::jsonb, 'A 52-year-old woman asks you to remove a lower third molar whose roots lie close to the inferior alveolar canal. She is anxious and says, "Just do whatever you think is best."', array['ADC','ethics','AHPRA']::text[]),
(17, 10, 'adc-avulsion', 'Avulsion of a Permanent Incisor', 'must_know', 'ADC – dental trauma', '{"definition":"Complete displacement of a tooth out of its socket. Prognosis depends mainly on extra-oral dry time, the storage medium and the stage of root development.","management":["Phone advice: find the tooth, hold it by the crown, rinse briefly if dirty (do not scrub the root) and replant immediately; otherwise store in milk, saline or saliva and come in at once","In the clinic: rinse with saline, replant with gentle pressure, check the position on a radiograph, and place a flexible splint for about 2 weeks","Open apex: allow a chance of pulp revascularisation and monitor closely; closed apex: start root canal treatment within 2 weeks","Systemic antibiotics (amoxicillin or penicillin in children; doxycycline only over 12 years), check tetanus status, chlorhexidine mouthwash, soft diet","Follow-up: 2 weeks, 4 weeks, 3 months, 6 months, 1 year, then yearly"],"clinical_features":["Dry time over 60 minutes: periodontal ligament cells are non-viable, so replacement resorption (ankylosis) is expected","Avulsed primary teeth are not replanted"],"viva_pearls":["Milk is the best widely available storage medium; Hank''s balanced salt solution is better if available.","IADT guidelines (2020) are the reference for dental trauma management."]}'::jsonb, '[{"q":"What should the mother have been told on the phone?","keywords":["replant","crown|hold","milk|saline|saliva","scrub|touch the root|rinse","immediately|straight away|urgent|at once"],"probe":"How should she handle and store the tooth?"},{"q":"How will you manage this in the clinic?","keywords":["saline|rinse","replant","radiograph|x ray|x-ray","flexible|splint","2 weeks|two weeks"],"probe":"What type of splint, and for how long?"},{"q":"What about the pulp in this 9-year-old?","keywords":["open apex|immature|incomplete","revascular|pulp healing","monitor|review|follow","root canal|endodontic"],"probe":"How does root development change your plan?"},{"q":"What medication and aftercare will you give?","keywords":["antibiotic|amoxicillin|penicillin|doxycycline","tetanus","chlorhexidine|mouthwash","soft diet","follow up|follow-up|review"],"probe":"Which antibiotic is suitable for a 9-year-old, and why not doxycycline?"}]'::jsonb, 'A 9-year-old was hit by a cricket ball 30 minutes ago. His mother has brought the avulsed upper right central incisor wrapped in a dry tissue.', array['ADC','trauma','IADT']::text[]),
(18, 1, 'oral-squamous-cell-carcinoma', 'Oral Squamous Cell Carcinoma', 'must_know', '10-mark essay', '{"definition":"A malignant epithelial neoplasm arising from the oral mucosal epithelium and showing squamous differentiation. It accounts for over 90% of oral cancers.","etiology":["Tobacco – smoked, and smokeless (gutka, khaini, betel quid)","Alcohol (synergistic with tobacco)","Areca nut","Human papillomavirus (HPV-16), especially in the oropharynx","Potentially malignant disorders: leukoplakia, erythroplakia, OSMF","UV light (lower lip); immunosuppression"],"clinical_features":["Commonest site in India: gingivobuccal sulcus and buccal mucosa (tobacco-quid habit); in the West: lateral tongue and floor of mouth","Non-healing ulcer with rolled, everted, indurated margins, or an exophytic growth or a red/white patch","Loose teeth, lip paraesthesia, trismus (spread into bone, nerve, muscle)","Hard, fixed cervical lymph nodes"],"classification":["TNM staging (AJCC 8th edition): depth of invasion is part of T stage; extranodal extension is part of N stage","Broders histological grading: well, moderately and poorly differentiated"],"investigations":["Incisional biopsy from the edge of the lesion (toluidine blue can guide the site)","CT/MRI for local extent; OPG for bone involvement","FNAC of nodes; PET-CT for advanced disease"],"histopathology":["Islands and cords of malignant squamous cells invading the connective tissue","Keratin pearls and individual cell keratinisation (well differentiated)","Nuclear and cellular pleomorphism, hyperchromatism, abnormal mitoses","Pattern at the invasive front predicts behaviour"],"management":["Surgery: wide excision with about 1 cm clinical margins; marginal or segmental mandibulectomy when bone is involved","Neck dissection: selective, modified radical or radical depending on nodal status","Reconstruction: radial forearm, anterolateral thigh, fibula or pectoralis major flaps","Adjuvant radiotherapy or chemoradiotherapy (cisplatin) for high-risk features such as positive margins or extranodal extension","Dental care before radiotherapy (extract unsaveable teeth 2–3 weeks earlier, fluoride trays) to reduce osteoradionecrosis risk"],"viva_pearls":["Gingivobuccal (\"Indian oral cancer\") reflects the tobacco-quid habit.","Biopsy from the margin, not the necrotic centre."]}'::jsonb, '[{"q":"Define oral squamous cell carcinoma.","keywords":["malignant","epithelial|epithelium|squamous","mucosa|mucosal|oral"],"probe":"From which tissue does it arise?"},{"q":"What are the aetiological factors?","keywords":["tobacco|gutka|khaini","alcohol","areca|betel","hpv|papilloma","leukoplakia|potentially malignant|premalignant"],"probe":"Which virus is linked to oropharyngeal cancer?"},{"q":"Describe the clinical features of this lesion.","keywords":["ulcer|non healing|non-healing","everted|rolled","indurat","lymph node|lymphadenopathy","fixed|hard"],"probe":"Describe the margins and the lymph nodes."},{"q":"Describe the histopathology and grading.","keywords":["keratin pearl","pleomorph","invasion|invasive|islands","broders","well|moderately|poorly"],"probe":"Which grading system do you know?"},{"q":"How will you manage this patient?","keywords":["excision|resection|mandibulectomy","margin","neck dissection","radiotherapy|chemo","reconstruct|flap"],"probe":"What do you do with the neck?"}]'::jsonb, 'A 58-year-old man who has chewed tobacco for 30 years has a non-healing ulcer in the left gingivobuccal sulcus for 3 months. It has rolled, everted, indurated margins, and there is a hard, fixed left submandibular lymph node.', array['oral cancer','tobacco']::text[]),
(19, 1, 'pleomorphic-adenoma', 'Pleomorphic Adenoma', 'must_know', '5-mark short note', '{"definition":"The most common salivary gland tumour: a benign \"mixed tumour\" of epithelial and myoepithelial cells in a mesenchymal-like (myxoid, chondroid) stroma.","clinical_features":["Parotid (superficial lobe) is the commonest site; the palate is the commonest intraoral site","30–50 years, female predilection","Painless, slow-growing, firm, rubbery, mobile swelling","Facial nerve weakness or rapid growth suggests malignant change"],"investigations":["FNAC and ultrasound; MRI for deep-lobe tumours","Avoid open incisional biopsy of a parotid lump (tumour seeding)"],"histopathology":["Incomplete fibrous capsule with pseudopod-like extensions","Ductal epithelial cells and myoepithelial cells (plasmacytoid, spindle, clear)","Myxoid, chondroid and hyalinised stroma"],"management":["Superficial parotidectomy with facial nerve preservation (total parotidectomy for deep lobe)","Never enucleate: pseudopods and capsule rupture cause recurrence","Palatal tumours: wide excision including the overlying periosteum","Complications of parotid surgery: facial nerve injury, Frey syndrome (gustatory sweating)"],"viva_pearls":["Long-standing tumours can transform: carcinoma ex pleomorphic adenoma.","Warthin tumour is the second most common parotid tumour."]}'::jsonb, '[{"q":"What is pleomorphic adenoma?","keywords":["benign","mixed","salivary","epithelial|myoepithelial","stroma|chondroid|myxoid"],"probe":"Why is it called a mixed tumour?"},{"q":"Where does it occur and how does it present?","keywords":["parotid","palate","painless","slow","firm|rubbery|mobile"],"probe":"What is the commonest intraoral site?"},{"q":"Describe the histopathology.","keywords":["capsule","pseudopod","myoepithelial","ductal|duct","chondroid|myxoid"],"probe":"What is special about the capsule?"},{"q":"How is it treated, and why not enucleation?","keywords":["superficial parotidectomy|parotidectomy","facial nerve","recurrence","pseudopod|capsule","frey"],"probe":"Which nerve must be preserved, and what late complication can occur?"}]'::jsonb, 'A 40-year-old woman has a painless, firm, rubbery swelling in front of the left ear that has grown slowly for 4 years. Facial nerve function is normal.', array['salivary gland tumour']::text[]),
(20, 2, 'pemphigus-vulgaris', 'Pemphigus Vulgaris', 'must_know', '10-mark essay', '{"definition":"A chronic autoimmune vesiculobullous disease in which IgG autoantibodies against desmoglein 3 (and desmoglein 1) cause loss of keratinocyte adhesion (acantholysis) and an intraepithelial blister.","clinical_features":["40–60 years","Oral lesions are often the first sign: flaccid bullae rupture quickly to leave painful, ragged erosions","Positive Nikolsky sign","Skin: flaccid bullae and crusted erosions"],"investigations":["Perilesional biopsy for H&E and direct immunofluorescence","Serum indirect immunofluorescence and ELISA for anti-desmoglein 1 and 3","Tzanck smear shows acantholytic (Tzanck) cells"],"histopathology":["Suprabasal (intraepithelial) cleft with acantholysis","Basal cells stay attached to the basement membrane – \"row of tombstones\"","DIF: intercellular IgG and C3 in a \"fishnet\" / \"chicken-wire\" pattern"],"management":["Refer to dermatology; systemic corticosteroids (prednisolone)","Steroid-sparing agents: azathioprine, mycophenolate; rituximab for moderate to severe disease","Topical steroids and good oral hygiene for oral lesions","Differential: mucous membrane pemphigoid – subepithelial split, linear basement-membrane IgG/C3"],"viva_pearls":["Intraepithelial split = pemphigus; subepithelial split = pemphigoid."]}'::jsonb, '[{"q":"What is pemphigus vulgaris?","keywords":["autoimmune","desmoglein","acantholysis","intraepithelial|suprabasal"],"probe":"Against which protein are the antibodies directed?"},{"q":"What clinical sign would you elicit?","keywords":["nikolsky","bullae|blister","erosion","flaccid"],"probe":"How do you elicit it?"},{"q":"Describe the histopathology and immunofluorescence.","keywords":["suprabasal","acantholy|tzanck","tombstone","fishnet|chicken wire|intercellular","igg"],"probe":"What pattern does direct immunofluorescence show?"},{"q":"How will you manage it, and how does it differ from pemphigoid?","keywords":["steroid|prednisolone","azathioprine|mycophenolate|rituximab","pemphigoid","subepithelial"],"probe":"Where is the split in pemphigoid?"}]'::jsonb, 'A 48-year-old woman has painful, ragged oral erosions for 2 months. Rubbing the normal-looking buccal mucosa near a lesion causes the epithelium to peel off.', array['vesiculobullous','autoimmune']::text[]),
(21, 2, 'trigeminal-neuralgia', 'Trigeminal Neuralgia', 'must_know', '5-mark short note', '{"definition":"Unilateral, paroxysmal, brief, electric-shock-like pain in the distribution of one or more divisions of the trigeminal nerve, triggered by innocuous stimuli.","etiology":["Classical: neurovascular compression of the trigeminal root, most often by the superior cerebellar artery","Secondary: multiple sclerosis (young, sometimes bilateral), cerebellopontine angle tumours"],"clinical_features":["Usually over 50 years; more common in women","Mandibular and maxillary divisions most often affected","Trigger zones: touching the face, shaving, brushing, eating","Attacks last seconds to 2 minutes, with refractory periods; no sensory loss in classical TN"],"investigations":["Clinical diagnosis","MRI to look for compression or a secondary cause","Diagnostic local anaesthetic block of the trigger zone"],"management":["Carbamazepine is the drug of choice; monitor blood counts, liver function and sodium; HLA-B*1502 screening in Asian patients (risk of SJS/TEN)","Alternatives: oxcarbazepine, baclofen, gabapentin, lamotrigine","Surgery: microvascular decompression (Jannetta)","Percutaneous procedures: radiofrequency rhizotomy, glycerol injection, balloon compression; gamma-knife radiosurgery","Peripheral options: alcohol injection, cryotherapy, peripheral neurectomy"],"viva_pearls":["Pain with sensory loss, or in a young patient, points to secondary TN – get an MRI."]}'::jsonb, '[{"q":"Define trigeminal neuralgia.","keywords":["unilateral","paroxysmal|sudden","electric|shock|lancinating","trigeminal"],"probe":"Describe the character and duration of the pain."},{"q":"What causes it?","keywords":["vascular|artery|compression","superior cerebellar","multiple sclerosis","tumour|tumor"],"probe":"Which vessel is usually responsible?"},{"q":"What is the drug of choice and what must you monitor?","keywords":["carbamazepine","blood count|cbc|haematolog|liver","hla","oxcarbazepine|baclofen|gabapentin"],"probe":"Which genetic test is advised in Asian patients?"},{"q":"What surgical options exist?","keywords":["microvascular decompression","rhizotomy|radiofrequency","glycerol|balloon","gamma knife|radiosurgery","neurectomy|alcohol"],"probe":"Which surgery addresses the cause?"}]'::jsonb, 'A 62-year-old woman has sudden, electric-shock-like pain in the right lower lip and chin, lasting seconds, triggered by brushing her teeth. Between attacks she is pain-free and sensation is normal.', array['orofacial pain']::text[]),
(22, 5, 'periodontitis-staging-grading', 'Periodontitis: 2017 Staging & Grading', 'must_know', '10-mark essay', '{"definition":"The 2017 World Workshop (AAP/EFP) classifies periodontitis by Stage (severity and complexity, I–IV), Grade (rate of progression, A–C) and Extent (localised, generalised, molar–incisor pattern).","classification":["Stage I: interdental CAL 1–2 mm, bone loss < 15% (coronal third), no tooth loss, probing depth ≤ 4 mm","Stage II: CAL 3–4 mm, bone loss 15–33%, no tooth loss, probing depth ≤ 5 mm, mostly horizontal bone loss","Stage III: CAL ≥ 5 mm, bone loss into the middle third or beyond, ≤ 4 teeth lost; probing depth ≥ 6 mm, vertical defects ≥ 3 mm, furcation class II/III","Stage IV: as Stage III plus ≥ 5 teeth lost, or a need for complex rehabilitation (masticatory dysfunction, bite collapse, < 20 remaining teeth)","Grade A: % bone loss ÷ age < 0.25, non-smoker, no diabetes","Grade B: 0.25–1.0, smoker < 10 cigarettes/day, HbA1c < 7%","Grade C: > 1.0, smoker ≥ 10/day or HbA1c ≥ 7%","Extent: localised < 30% of teeth, generalised ≥ 30%, or molar–incisor pattern"],"management":["Step 1: oral hygiene instruction, risk-factor control (smoking cessation, glycaemic control), supragingival debridement","Step 2: subgingival instrumentation (scaling and root planing) ± adjuncts","Step 3: re-evaluate; periodontal surgery for residual deep pockets","Step 4: supportive periodontal therapy at regular recall"],"viva_pearls":["Stage is set by the worst interdental site; complexity factors can raise the stage.","Grade is shifted upward by smoking and diabetes."]}'::jsonb, '[{"q":"What are the components of the 2017 classification of periodontitis?","keywords":["stage","grade","extent|localised|generalised","severity|complexity","progression|rate"],"probe":"What does the stage describe, and what does the grade describe?"},{"q":"What stage is this patient, and why?","keywords":["stage iii|stage 3|three","attachment loss|cal|5 mm|6 mm","middle third","tooth loss|lost 2|four or fewer"],"probe":"Look at CAL, bone loss and tooth loss."},{"q":"What grade is this patient?","keywords":["grade c|c","smok|10 cigarettes","bone loss|age","1.0|ratio"],"probe":"How do smoking and the bone loss/age ratio affect the grade?"},{"q":"Outline the steps of treatment.","keywords":["oral hygiene|risk factor|smoking cessation","scaling|root planing|subgingival","surgery|surgical","maintenance|supportive|recall"],"probe":"What comes after non-surgical therapy?"}]'::jsonb, 'A 42-year-old who smokes 15 cigarettes a day has interdental attachment loss of 6 mm on several molars, bone loss to the middle third of the roots, and has lost 2 molars to periodontitis. Bone loss on the worst tooth is about 50%.', array['2017 classification']::text[]),
(23, 4, 'dental-caries', 'Dental Caries', 'must_know', '10-mark essay', '{"definition":"A biofilm-mediated, sugar-driven, multifactorial, dynamic disease that causes alternating demineralisation and remineralisation of dental hard tissues, leading to net mineral loss.","etiology":["Keyes'' triad – host (tooth), microflora, substrate – with time added by Newbrun","Miller''s chemoparasitic (acidogenic) theory, 1890; proteolysis and proteolysis–chelation theories","Ecological plaque hypothesis (Marsh)","Streptococcus mutans initiates; lactobacilli drive progression; Actinomyces in root caries","Critical pH: about 5.5 for enamel; the Stephan curve shows pH fall after sugar"],"classification":["G.V. Black classes by site","Pit and fissure, smooth surface and root caries","Acute (rampant), chronic, arrested and secondary (recurrent) caries","ICDAS II codes 0–6; Mount and Hume site/size system"],"clinical_features":["White spot lesion – the earliest clinically visible sign (reversible)","Brown spot, then cavitation"],"investigations":["Visual-tactile examination on clean, dry teeth","Bitewing radiographs","Transillumination (FOTI), laser fluorescence (DIAGNOdent)","Caries risk assessment (e.g. CAMBRA)"],"histopathology":["Enamel lesion zones (from the advancing front): translucent zone, dark zone, body of the lesion, surface zone","Dentine zones: fatty degeneration of Tomes'' fibres, dentinal sclerosis, decalcification, bacterial invasion, decomposed dentine"],"management":["Prevention: fluoride, fissure sealants, diet counselling","Remineralisation of non-cavitated lesions (fluoride varnish, CPP-ACP)","Minimal intervention: selective caries removal, then restoration"],"viva_pearls":["The surface zone of an enamel lesion stays relatively intact – the reason white spots can remineralise."]}'::jsonb, '[{"q":"Define dental caries.","keywords":["biofilm|plaque","sugar|carbohydrate","multifactorial","demineralisation|demineralization","dynamic|remineralisation|remineralization"],"probe":"Is it a static or a dynamic process?"},{"q":"Explain its aetiology.","keywords":["keyes|triad","host|tooth","microflora|bacteria|mutans","substrate|sugar","time"],"probe":"Who added time to the triad?"},{"q":"Which theories of caries do you know?","keywords":["miller|acidogenic|chemoparasitic","proteolysis","chelation","ecological"],"probe":"Who proposed the chemoparasitic theory?"},{"q":"Describe the zones of an enamel lesion.","keywords":["translucent","dark","body","surface"],"probe":"Start from the advancing front."},{"q":"How would you manage these white spot lesions?","keywords":["fluoride|varnish","diet","remineral","cpp|casein","sealant|monitor"],"probe":"Do they need drilling?"}]'::jsonb, 'A 19-year-old student who sips sweetened tea through the day has chalky white spots along the gingival margins of several teeth and a cavitated lesion on the occlusal surface of 36.', array['caries','cariology']::text[]),
(24, 4, 'root-canal-irrigants', 'Root Canal Irrigants', 'desirable', '5-mark short note', '{"definition":"Solutions used during cleaning and shaping to flush debris, dissolve pulp tissue, kill microorganisms and remove the smear layer from areas instruments cannot reach.","classification":["Sodium hypochlorite 0.5–5.25%: dissolves organic tissue and is strongly antibacterial; does not remove the inorganic smear layer","EDTA 17%: chelator that removes the inorganic part of the smear layer; final rinse for about 1 minute","Chlorhexidine 2%: substantivity, effective against Enterococcus faecalis; does not dissolve tissue","MTAD (doxycycline, citric acid, detergent); saline as an inert flush"],"management":["Use a side-vented 30-gauge needle 1–2 mm short of working length, never binding in the canal; gentle pressure","Activate irrigants with sonic or ultrasonic agitation, or negative-pressure systems","NaOCl followed directly by chlorhexidine forms a brown precipitate (para-chloroaniline): flush with saline or alcohol in between","NaOCl accident: stop, reassure, give local anaesthetic and analgesics, cold compresses first then warm, antibiotics if infection is likely, and refer urgently if the airway is threatened"],"viva_pearls":["Ideal irrigant: tissue-dissolving, antibacterial, removes smear layer, non-toxic to periapical tissue – no single irrigant does all."]}'::jsonb, '[{"q":"Why do we irrigate root canals?","keywords":["debris|flush","dissolve|tissue","antibacterial|microorganisms|disinfect","smear layer","lubricat"],"probe":"Name four functions."},{"q":"Compare sodium hypochlorite, EDTA and chlorhexidine.","keywords":["hypochlorite|naocl","dissolv","edta|chelat","smear layer","chlorhexidine|substantivity"],"probe":"Which one removes the smear layer?"},{"q":"What happens if you use NaOCl and chlorhexidine one after the other?","keywords":["precipitate","brown|orange","chloroaniline|pca","saline|alcohol|flush"],"probe":"How do you prevent it?"},{"q":"This patient has had a hypochlorite accident. How will you manage it?","keywords":["stop|reassure","analgesic|anaesthe","cold|ice|compress","antibiotic","refer|airway|hospital"],"probe":"What do you do if the swelling threatens the airway?"}]'::jsonb, 'While irrigating a lower premolar with sodium hypochlorite, your patient suddenly complains of severe burning pain, and the cheek starts to swell within seconds.', array['endodontics']::text[]),
(25, 7, 'fluorides', 'Fluorides in Dentistry', 'must_know', '10-mark essay', '{"definition":"Fluoride prevents caries mainly by a topical, post-eruptive action: it enhances remineralisation (forming fluorhydroxyapatite), inhibits demineralisation and interferes with bacterial metabolism (enolase).","classification":["Systemic: community water fluoridation (about 0.7 ppm; lower in hot climates), salt and milk fluoridation, supplements","Professional topical: 1.23% APF gel (12,300 ppm, pH about 3.5, 4 minutes); 2% NaF (Knutson technique: 4 applications a week apart at ages 3, 7, 11, 13); 8% SnF₂; 5% NaF varnish (22,600 ppm); 38% silver diamine fluoride (arrests caries, stains black)","Self-applied: toothpaste 1000–1500 ppm (a rice-grain smear under 3 years, pea-sized from 3 to 6 years), mouthrinses"],"clinical_features":["Acute toxicity doses: probably toxic dose 5 mg F/kg (needs hospital care); safely tolerated dose 8–16 mg/kg; certainly lethal dose 32–64 mg/kg in adults","Chronic excess in childhood causes dental fluorosis (graded by Dean''s index); skeletal fluorosis with high, long-term intake"],"management":["Calculate the dose: 100 g × 1 mg F/g = 100 mg F ÷ 16 kg ≈ 6.25 mg/kg – above the probably toxic dose","Give milk or another calcium source to bind fluoride and send the child to hospital at once","Below 5 mg/kg: oral calcium (milk) and observe for a few hours"],"viva_pearls":["1000 ppm = 1 mg fluoride per gram of toothpaste."]}'::jsonb, '[{"q":"How does fluoride prevent caries?","keywords":["topical|post eruptive|posteruptive","remineral","demineral","fluorapatite|fluorhydroxyapatite","enolase|bacteria"],"probe":"Is the main action systemic or topical?"},{"q":"List the professionally applied topical fluorides.","keywords":["apf|acidulated","sodium fluoride|naf|knutson","stannous|snf","varnish|duraphat","silver diamine|sdf"],"probe":"What is Knutson''s technique?"},{"q":"What are the toxic doses of fluoride?","keywords":["probably toxic|ptd|5 mg","safely tolerated|std","certainly lethal|cld|32"],"probe":"What is the probably toxic dose?"},{"q":"How will you manage this child?","keywords":["calculate|mg/kg|6","milk|calcium","hospital|emergency","observe|monitor"],"probe":"Work out the dose this child took."}]'::jsonb, 'A 4-year-old weighing 16 kg swallowed most of a 100 g tube of 1000 ppm fluoride toothpaste about 20 minutes ago. The parent calls your clinic.', array['prevention','public health']::text[]),
(26, 7, 'behaviour-management', 'Behaviour Management in Children', 'must_know', '10-mark essay', '{"definition":"The set of communication and clinical techniques used to build trust, reduce fear and enable safe, effective dental care for a child, with a positive attitude to dentistry as the long-term goal.","classification":["Frankl scale: 1 definitely negative, 2 negative, 3 positive, 4 definitely positive","Wright''s classification: cooperative, lacking cooperative ability, potentially cooperative"],"management":["Communication: age-appropriate language, euphemisms, active listening","Tell-show-do (Addelston): explain, demonstrate, then perform","Positive reinforcement, distraction, modelling (a sibling or video), desensitisation","Voice control and parental presence/absence (with informed consent)","Protective stabilisation only when necessary, with consent and documentation; hand-over-mouth is no longer an accepted technique","Pharmacological: nitrous oxide–oxygen inhalation sedation (100% oxygen for 3–5 minutes afterwards to prevent diffusion hypoxia), oral midazolam, general anaesthesia for extensive treatment or non-cooperative children"],"viva_pearls":["Start with simple, non-invasive work (prophylaxis, fluoride) on the first visit to build trust."]}'::jsonb, '[{"q":"How do you classify child behaviour?","keywords":["frankl","definitely negative|definitely positive","wright","potentially cooperative|lacking cooperative"],"probe":"Give me the Frankl scale."},{"q":"What is tell-show-do?","keywords":["tell","show","do","addelston","explain|demonstrat"],"probe":"Who introduced it, and how is it done?"},{"q":"Which other non-pharmacological techniques will you use for this child?","keywords":["positive reinforcement|praise","distraction","modelling|modeling","voice control","desensiti|parental presence"],"probe":"Name at least four."},{"q":"If he still cannot cooperate, what are your pharmacological options?","keywords":["nitrous oxide|inhalation","diffusion hypoxia|100% oxygen","midazolam|oral sedation","general anaesthesia|general anesthesia"],"probe":"What must you give at the end of nitrous oxide sedation?"}]'::jsonb, 'A 5-year-old on his first dental visit hides behind his mother, cries and refuses to open his mouth. He needs restorations in two primary molars.', array['child psychology']::text[]),
(27, 11, 'angle-classification', 'Angle''s Classification of Malocclusion', 'must_know', '5-mark short note', '{"definition":"Edward Angle (1899) classified malocclusion by the anteroposterior relationship of the permanent first molars, which he called the \"key to occlusion\".","classification":["Class I: the mesiobuccal cusp of the maxillary first molar occludes in the buccal groove of the mandibular first molar","Class II: the mandibular arch is distal – the mesiobuccal cusp lies mesial to (ahead of) the buccal groove","Class II division 1: proclined maxillary incisors with increased overjet","Class II division 2: retroclined maxillary central incisors, often with flared laterals and a deep bite","Subdivision: the Class II or III relation exists on one side only","Class III: the mandibular arch is mesial to the maxillary arch"],"clinical_features":["Drawbacks: considers only the anteroposterior plane (ignores vertical and transverse)","Describes dental, not skeletal, relationships","Assumes the first molar position is fixed; cannot be used when first molars are missing"],"management":["Other systems: Dewey''s modification (types of Class I), Ackerman–Proffit (Venn diagram), Simon''s three planes, incisor classification (BSI), canine relationship"],"viva_pearls":["This case is Class II division 1 (molars distal bilaterally, proclined incisors, increased overjet)."]}'::jsonb, '[{"q":"What is Angle''s classification based on?","keywords":["first molar|molar","key to occlusion","anteroposterior|sagittal","mesiobuccal cusp","buccal groove"],"probe":"Which tooth did Angle call the key to occlusion?"},{"q":"Describe Class II and its divisions.","keywords":["distal","division 1|proclined","division 2|retroclined","overjet|deep bite","subdivision"],"probe":"How do the incisors differ between the two divisions?"},{"q":"Classify this patient.","keywords":["class ii|class 2","division 1|div 1","bilateral|both sides","overjet"],"probe":"Look at the molars and the incisors."},{"q":"What are the drawbacks of Angle''s classification?","keywords":["anteroposterior only|vertical|transverse","skeletal","missing molar|molar missing","fixed|stable"],"probe":"Which planes does it ignore?"}]'::jsonb, 'A 12-year-old has proclined upper incisors with a 9 mm overjet. With the teeth together, the mesiobuccal cusp of the upper first molar sits mesial to the buccal groove of the lower first molar on both sides.', array['malocclusion']::text[]),
(28, 3, 'mandibular-fractures', 'Fractures of the Mandible', 'must_know', '10-mark essay', '{"definition":"A break in the continuity of the mandible. Its site and direction decide how the muscles displace the fragments and how it is treated.","classification":["By site: condyle, coronoid, ramus, angle, body, parasymphysis, symphysis, dentoalveolar","Favourable or unfavourable, horizontally and vertically, depending on whether muscle pull holds the fragments together or pulls them apart","Simple, compound, comminuted, greenstick, pathological"],"clinical_features":["Step deformity and derangement of occlusion; abnormal mobility; pain and trismus","Sublingual haematoma (Coleman''s sign) in body and parasymphysis fractures","Paraesthesia of the lower lip from inferior alveolar nerve injury","Bilateral parasymphyseal fracture: the tongue can fall back and obstruct the airway","Bilateral condylar fractures: anterior open bite; unilateral: chin deviates to the injured side"],"investigations":["OPG; PA mandible; reverse Towne view for condyles; CT for complex or condylar fractures"],"management":["ATLS: airway first (pull the tongue forward in flail anterior segments), control bleeding, check the cervical spine","Closed reduction and intermaxillary fixation (arch bars, eyelet wiring) for about 4–6 weeks","Open reduction and internal fixation with monocortical miniplates along Champy''s ideal lines of osteosynthesis","Condyle: mostly conservative or closed treatment (especially in children); ORIF for specific indications (e.g. displacement into the middle cranial fossa, inability to restore occlusion)","Antibiotics for compound fractures; assess teeth in the fracture line"],"viva_pearls":["A step between 33 and 34 with lip numbness suggests a body/parasymphysis fracture involving the mental or inferior alveolar nerve."]}'::jsonb, '[{"q":"How do you classify mandibular fractures?","keywords":["condyle|condylar","angle","body|parasymphysis|symphysis","favourable|favorable|unfavourable","compound|comminuted|simple"],"probe":"What makes a fracture favourable?"},{"q":"What signs would you look for?","keywords":["step","occlusion|bite","sublingual haematoma|sublingual hematoma|coleman","paraesthesia|paresthesia|numbness","mobility"],"probe":"What is Coleman''s sign?"},{"q":"Which radiographs will you take?","keywords":["opg|orthopantomogram|panoramic","pa mandible|posteroanterior","towne","ct|computed tomography"],"probe":"Which view shows the condyles best?"},{"q":"How will you treat this fracture?","keywords":["airway|atls","imf|mmf|intermaxillary|arch bar","orif|open reduction|miniplate","champy","antibiotic"],"probe":"Where do you place the miniplates?"}]'::jsonb, 'A 24-year-old was assaulted. He has a step in the lower teeth between 33 and 34, a sublingual haematoma, numbness of the left lower lip and a deranged bite.', array['trauma']::text[]),
(29, 3, 'ludwigs-angina', 'Ludwig''s Angina', 'must_know', '10-mark essay', '{"definition":"A rapidly spreading, bilateral cellulitis (not a localised abscess) involving the submandibular, sublingual and submental spaces, which can rapidly obstruct the airway.","etiology":["Mostly odontogenic – mandibular second and third molars, whose roots lie below the mylohyoid line","Mixed streptococci and oral anaerobes","Risk factors: diabetes, immunosuppression, poor oral hygiene"],"clinical_features":["Bilateral, brawny, board-like swelling of the floor of the mouth and neck","Elevated, protruding tongue; drooling; dysphagia; trismus","Muffled \"hot potato\" voice, stridor, fever and toxicity"],"investigations":["Assess the airway first; CT neck with contrast when safe","Blood count, glucose, cultures of pus"],"management":["Secure the airway: awake fibreoptic intubation or tracheostomy under local anaesthesia","High-dose IV antibiotics (e.g. amoxicillin–clavulanate or penicillin with metronidazole; clindamycin if allergic)","Early surgical decompression: incision and drainage of all involved spaces, with drains","Remove the source (extract the offending tooth), IV fluids, control blood sugar, ICU care"],"viva_pearls":["Complications: airway obstruction, descending mediastinitis, septicaemia – this is an emergency."]}'::jsonb, '[{"q":"What is Ludwig''s angina?","keywords":["cellulitis","bilateral","submandibular","sublingual","submental"],"probe":"Which three spaces are involved, and is it an abscess?"},{"q":"Why do lower molars cause it?","keywords":["mylohyoid","below|apices|roots","second|third molar","submandibular"],"probe":"Relate the root apices to the mylohyoid muscle."},{"q":"What is your first priority?","keywords":["airway","intubation|fibreoptic|fiberoptic","tracheostomy"],"probe":"How will you secure the airway if intubation is difficult?"},{"q":"Describe the rest of the management.","keywords":["antibiotic|amoxicillin|penicillin|clindamycin|metronidazole","incision|drainage|decompression","extract|remove the source","fluids|icu|glucose"],"probe":"Is antibiotic therapy alone enough?"}]'::jsonb, 'A 35-year-old with a decayed 37 has a hard, board-like swelling under both sides of the jaw. The tongue is raised, he is drooling, his voice is muffled and he cannot swallow saliva. Temperature 39 °C.', array['fascial space infection','emergency']::text[]),
(30, 6, 'jaw-relations', 'Jaw Relations in Complete Dentures', 'must_know', '10-mark essay', '{"definition":"Jaw relation is any spatial relationship of the mandible to the maxilla. It is recorded as orientation (face-bow), vertical (VDO and VDR) and horizontal (centric and eccentric) relations.","classification":["Orientation relation: face-bow transfer (arbitrary or kinematic)","Vertical relations: vertical dimension at rest (VDR) and in occlusion (VDO)","Horizontal relations: centric relation and eccentric relations (protrusive, lateral)"],"investigations":["VDO = VDR minus the freeway space (about 2–4 mm)","Vertical dimension methods: physiological rest position, phonetics (\"S\" sounds – closest speaking space; \"M\" to find rest), swallowing, facial measurements (Willis gauge, Niswonger), pre-extraction records","Centric relation methods: Gothic arch (needle-point) tracing, interocclusal records, swallowing and tongue-retrusion techniques"],"clinical_features":["Increased VDO: clicking teeth during speech, sore ridges, strained face, loss of freeway space","Decreased VDO: collapsed lips, angular cheilitis, reduced chewing efficiency, possible TMJ symptoms (Costen''s syndrome)"],"viva_pearls":["Centric relation is a bone-to-bone, reproducible, physiological position – the starting point for complete denture occlusion."]}'::jsonb, '[{"q":"What are jaw relations, and how are they classified?","keywords":["spatial relationship|relationship of mandible","orientation|face bow|face-bow","vertical","horizontal|centric"],"probe":"Name the three groups."},{"q":"How do you determine the vertical dimension?","keywords":["rest|physiologic","freeway space|interocclusal","phonetic|s sound|speech","swallowing","willis|niswonger|facial measurement"],"probe":"What is the freeway space?"},{"q":"What happens with an increased or decreased VDO?","keywords":["clicking|click","sore|ridge","angular cheilitis","collapsed|lips","costen|tmj"],"probe":"Which patient in the case has which error?"},{"q":"How do you record centric relation?","keywords":["gothic arch|needle point|arrow point","interocclusal|record","swallowing|tongue","reproducible|retruded"],"probe":"What does the apex of a Gothic arch tracing represent?"}]'::jsonb, 'A new complete denture patient complains that his teeth "click" when he talks, his ridges are sore and his face looks strained. In another patient the lips look collapsed and there is angular cheilitis.', array['complete denture']::text[])
insert into public.flashcards (id, topic_id, front, back) overriding system value values
(1, 1, 'What are the Vickers–Gorlin criteria?', 'Early histological features of ameloblastoma: hyperchromatic basal-cell nuclei, palisading with reverse polarity, and subnuclear cytoplasmic vacuolation.'),
(2, 1, 'Most common histological pattern of ameloblastoma?', 'Follicular.'),
(3, 1, 'Which ameloblastoma mimics a fibro-osseous lesion on radiographs?', 'Desmoplastic ameloblastoma – mixed radiolucent–radiopaque, often in the anterior maxilla.'),
(4, 1, 'Treatment of mural unicystic ameloblastoma?', 'Treat like the conventional tumour – resection with safe bony margins.'),
(5, 2, 'Typical aspirate of an OKC?', 'Thick, cheesy, creamy fluid with keratin squames; soluble protein < 4 g/dL.'),
(6, 2, 'Histology hallmark of OKC?', 'Uniform 6–8 layer parakeratinised epithelium with a corrugated surface and palisaded "tombstone" basal cells.'),
(7, 2, 'Gene mutated in Gorlin–Goltz syndrome?', 'PTCH1 (patched) – a tumour suppressor in the Hedgehog pathway.'),
(8, 3, 'Most common odontogenic cyst?', 'Radicular (periapical) cyst.'),
(9, 3, 'Rushton bodies are seen in?', 'Radicular and dentigerous cysts – hyaline, curved, eosinophilic bodies in the epithelial lining.'),
(10, 4, 'Earliest symptom of OSMF?', 'Burning sensation on eating spicy food (often with vesicles).'),
(11, 4, 'Role of copper in OSMF?', 'Areca nut is rich in copper, which up-regulates lysyl oxidase → increased collagen cross-linking.'),
(12, 4, 'Khanna & Andrade group III mouth opening?', '15–26 mm (moderately advanced).'),
(13, 5, 'Is leukoplakia a clinical or histological term?', 'Clinical – the diagnosis is made by excluding other white lesions.'),
(14, 5, 'Highest-risk type of leukoplakia?', 'Proliferative verrucous leukoplakia (and non-homogeneous / speckled forms).'),
(15, 6, 'Civatte bodies are?', 'Apoptotic (degenerated) basal keratinocytes seen in lichen planus.'),
(16, 6, '6 Ps of cutaneous lichen planus?', 'Pruritic, purple, polygonal, planar papules and plaques.'),
(17, 7, 'Most difficult angulation of mandibular third molar to remove?', 'Distoangular.'),
(18, 7, 'Pell & Gregory Class III?', 'All or most of the third molar lies within the ramus.'),
(19, 7, 'WAR line "Red" indicates?', 'Depth of the tooth / amount of bone to remove – each mm of red line ≈ greater difficulty.'),
(20, 8, 'Structure involved in all Le Fort fractures?', 'Pterygoid plates.'),
(21, 8, 'Guérin''s sign?', 'Ecchymosis in the region of the greater palatine vessels – seen in Le Fort I fracture.'),
(22, 9, 'Radiopacifier in MTA?', 'Bismuth oxide (also a cause of discolouration).'),
(23, 9, 'Setting time of MTA vs Biodentine?', 'MTA ≈ 165 minutes; Biodentine ≈ 12 minutes.'),
(24, 10, 'Antibiotic that may reduce cyclosporine-induced gingival enlargement?', 'Azithromycin.'),
(25, 11, 'Kennedy class with no modification spaces?', 'Class IV.'),
(26, 11, 'Who gave rules for applying Kennedy''s classification?', 'O. C. Applegate – 8 rules.'),
(27, 12, 'Final restoration after pulpotomy in a primary molar?', 'Stainless steel crown.'),
(28, 12, 'Ferric sulphate concentration and time in pulpotomy?', '15.5% for about 15 seconds.'),
(29, 13, 'Phase eliminated in high-copper amalgam?', 'γ₂ (Sn₇₋₈Hg).'),
(30, 13, 'Cause of delayed expansion of amalgam?', 'Zinc-containing alloy contaminated by moisture → hydrogen gas.'),
(31, 14, 'Max dose of lignocaine with adrenaline?', '7 mg/kg (max 500 mg). Without adrenaline: 4.4 mg/kg (max 300 mg).'),
(32, 14, 'LA causing methaemoglobinaemia?', 'Prilocaine (metabolite o-toluidine). Also benzocaine.'),
(33, 14, 'Most cardiotoxic LA?', 'Bupivacaine.'),
(34, 15, 'Adult adrenaline dose for anaphylaxis?', '0.01 mg/kg IM, maximum 0.5 mg (0.5 mL of 1:1000), anterolateral thigh; repeat every 5 minutes if needed.'),
(35, 15, 'Why should a patient in anaphylaxis not stand up?', 'Standing can cause sudden cardiovascular collapse; keep them lying flat (or sitting if breathing is difficult).'),
(36, 16, 'Australian case defining material risk?', 'Rogers v Whitaker (1992), High Court of Australia.'),
(37, 16, 'Four types of notifiable conduct (National Law)?', 'Practising while intoxicated; sexual misconduct in practice; impairment placing the public at substantial risk; significant departure from accepted professional standards.'),
(38, 17, 'Splint for a replanted avulsed permanent tooth?', 'Flexible splint for about 2 weeks.'),
(39, 17, 'Best widely available storage medium for an avulsed tooth?', 'Milk (Hank''s balanced salt solution if available).'),
(40, 18, 'Most common site of oral cancer in India?', 'Gingivobuccal sulcus / buccal mucosa (linked to the tobacco-quid habit).'),
(41, 18, 'Which TNM edition added depth of invasion to oral cancer T staging?', 'AJCC 8th edition (also added extranodal extension to N).'),
(42, 19, 'Most common salivary gland tumour?', 'Pleomorphic adenoma (parotid, superficial lobe).'),
(43, 19, 'Why is enucleation of pleomorphic adenoma avoided?', 'Incomplete capsule with pseudopods – enucleation leaves tumour behind and causes recurrence.'),
(44, 20, 'Target antigen in pemphigus vulgaris?', 'Desmoglein 3 (mucosal) ± desmoglein 1.'),
(45, 20, 'DIF pattern in pemphigus vulgaris?', 'Intercellular IgG/C3 – "fishnet" or "chicken-wire" pattern.'),
(46, 21, 'Drug of choice for trigeminal neuralgia?', 'Carbamazepine (screen HLA-B*1502 in Asian patients).'),
(47, 21, 'Usual vessel compressing the trigeminal root?', 'Superior cerebellar artery.'),
(48, 22, 'Grade C criteria for periodontitis?', '% bone loss ÷ age > 1.0, or smoker ≥ 10/day, or HbA1c ≥ 7%.'),
(49, 22, 'What moves a Stage III case to Stage IV?', '≥ 5 teeth lost to periodontitis or need for complex rehabilitation (e.g. bite collapse, < 20 teeth).'),
(50, 23, 'Four zones of an enamel caries lesion (from the front)?', 'Translucent zone, dark zone, body of the lesion, surface zone.'),
(51, 23, 'Critical pH for enamel demineralisation?', 'About 5.5.'),
(52, 24, 'Irrigant that removes the inorganic smear layer?', 'EDTA 17% (chelating agent).'),
(53, 24, 'NaOCl + chlorhexidine produce?', 'A brown precipitate (para-chloroaniline) – rinse between them.'),
(54, 25, 'Probably toxic dose of fluoride?', '5 mg F per kg body weight – needs immediate treatment and hospital care.'),
(55, 25, 'Concentration of fluoride in 1.23% APF gel?', '12,300 ppm (pH about 3.5).'),
(56, 26, 'Frankl rating "2"?', 'Negative – reluctant to accept treatment, some evidence of negative attitude.'),
(57, 26, 'Why give 100% oxygen after N₂O sedation?', 'To prevent diffusion hypoxia.'),
(58, 27, 'Angle Class II div 2 incisors?', 'Retroclined maxillary central incisors (laterals often flared), deep bite.'),
(59, 27, '"Key to occlusion" per Angle?', 'Maxillary permanent first molar.'),
(60, 28, 'Coleman''s sign?', 'Sublingual haematoma – suggests a fracture of the mandibular body/parasymphysis.'),
(61, 28, 'Bilateral condylar fracture causes?', 'Anterior open bite (posterior gagging of occlusion).'),
(62, 29, 'Spaces involved in Ludwig''s angina?', 'Bilateral submandibular, sublingual and submental spaces.'),
(63, 29, 'First priority in Ludwig''s angina?', 'Securing the airway (fibreoptic intubation or tracheostomy).'),
(64, 30, 'Freeway space?', 'VDR − VDO, about 2–4 mm.'),
(65, 30, 'Clicking of teeth during speech in new dentures suggests?', 'Increased vertical dimension of occlusion.')
insert into public.spotters (id, subject_id, topic_id, category, title, image_url, stain, key_findings, differentials, distractors, diagnostic_pearl, uses, difficulty) overriding system value values
(1, 1, 1, 'radiograph', 'Ameloblastoma (multilocular radiolucency)', 'spotters/r-ameloblastoma.svg', null, array['Multilocular "soap-bubble" radiolucency in the molar–ramus region','Expansion and thinning of the cortex','Knife-edge resorption of adjacent molar roots']::text[], array['Odontogenic keratocyst','Central giant cell granuloma','Odontogenic myxoma']::text[], array['Odontogenic keratocyst','Central giant cell granuloma','Radicular cyst']::text[], 'Large loculi = soap-bubble; small loculi = honeycomb. Root resorption favours ameloblastoma over OKC.', array[]::text[], 1),
(2, 1, 3, 'radiograph', 'Radicular cyst', 'spotters/r-radicular-cyst.svg', null, array['Well-defined, round, corticated radiolucency at the apex','Associated tooth has deep caries (non-vital)','Loss of lamina dura at the apex']::text[], array['Periapical granuloma','Periapical abscess']::text[], array['Periapical cemento-osseous dysplasia','Dentigerous cyst','Stafne bone cavity']::text[], 'Always check vitality – a radicular cyst is always associated with a non-vital tooth.', array[]::text[], 1),
(3, 1, null, 'radiograph', 'Dentigerous cyst', 'spotters/r-dentigerous-cyst.svg', null, array['Unilocular radiolucency around the crown of an unerupted third molar','Attached at the cemento-enamel junction','Well-corticated margin']::text[], array['Hyperplastic follicle (< 3–4 mm space)','Unicystic ameloblastoma','OKC']::text[], array['Radicular cyst','Odontoma','Calcifying odontogenic cyst']::text[], 'Pericoronal space > 5 mm suggests a dentigerous cyst rather than a normal follicle.', array[]::text[], 1),
(4, 2, null, 'radiograph', 'Osteosarcoma (sunray appearance)', 'spotters/r-osteosarcoma.svg', null, array['Spicules of new bone radiating outward ("sunray / sunburst")','Ill-defined, destructive margins','Symmetrical widening of the PDL space (Garrington sign)']::text[], array['Ewing sarcoma (onion-skin)','Chondrosarcoma','Metastatic prostate carcinoma']::text[], array['Fibrous dysplasia','Paget disease','Osteomyelitis']::text[], 'Garrington sign (symmetric PDL widening) is an early sign of jaw osteosarcoma.', array[]::text[], 2),
(5, 2, null, 'radiograph', 'Fibrous dysplasia (ground-glass)', 'spotters/r-fibrous-dysplasia.svg', null, array['Ground-glass (orange-peel) opacity','Margins blend imperceptibly into normal bone','Expansion with displacement of teeth; maxilla more common']::text[], array['Ossifying fibroma (well-defined)','Paget disease (cotton-wool)']::text[], array['Osteosarcoma','Ameloblastoma','Cherubism']::text[], 'Ill-defined margins = fibrous dysplasia; well-defined with a lucent rim = ossifying fibroma.', array[]::text[], 2),
(6, 1, 1, 'histology', 'Follicular ameloblastoma', 'spotters/h-ameloblastoma.svg', 'H&E, 10×', array['Islands (follicles) of odontogenic epithelium','Peripheral tall columnar cells with reverse polarity','Central stellate reticulum-like cells']::text[], array['Ameloblastic fibroma','Adenomatoid odontogenic tumour']::text[], array['Odontogenic keratocyst','Pleomorphic adenoma','Squamous cell carcinoma']::text[], 'Reverse polarity: nuclei move away from the basement membrane.', array[]::text[], 1),
(7, 1, 2, 'histology', 'Odontogenic keratocyst', 'spotters/h-okc.svg', 'H&E, 20×', array['Thin, uniform epithelium of 6–8 cell layers','Corrugated parakeratin surface','Palisaded "tombstone" basal cells; flat interface']::text[], array['Orthokeratinised odontogenic cyst','Dentigerous cyst']::text[], array['Radicular cyst','Ameloblastoma','Lichen planus']::text[], 'Corrugated parakeratin + palisaded basal layer + flat interface = OKC.', array[]::text[], 2),
(8, 2, 6, 'histology', 'Lichen planus', 'spotters/h-lichen-planus.svg', 'H&E, 10×', array['Saw-tooth rete ridges','Dense band-like subepithelial lymphocytic infiltrate','Basal cell liquefaction; Civatte bodies']::text[], array['Lichenoid drug reaction','Lupus erythematosus']::text[], array['Leukoplakia with dysplasia','Pemphigus vulgaris','Oral submucous fibrosis']::text[], 'Band-like lymphocytes hugging the basement membrane is the key to lichen planus.', array[]::text[], 2),
(9, 1, null, 'histology', 'Well-differentiated squamous cell carcinoma', 'spotters/h-scc.svg', 'H&E, 10×', array['Invasive islands of malignant squamous epithelium in connective tissue','Keratin pearls (concentric lamellated keratin)','Cellular and nuclear pleomorphism']::text[], array['Verrucous carcinoma','Pseudoepitheliomatous hyperplasia']::text[], array['Ameloblastoma','Basal cell carcinoma','Odontogenic keratocyst']::text[], 'Keratin pearls indicate a well-differentiated SCC (Broders grade I).', array[]::text[], 1),
(10, 5, null, 'instrument', 'WHO (CPITN) periodontal probe', 'spotters/i-who-probe.svg', null, array['0.5 mm ball tip','Black band from 3.5 to 5.5 mm','Further markings at 8.5 and 11.5 mm']::text[], array['Williams probe','UNC-15 probe']::text[], array['Williams probe','Nabers probe','Explorer No. 23']::text[], 'Light probing force of about 20–25 g.', array['Community Periodontal Index (CPI / CPITN)','Ball tip detects calculus and avoids over-penetration']::text[], 1),
(11, 3, null, 'instrument', 'Straight elevator', 'spotters/i-straight-elevator.svg', null, array['Straight shank with concave blade','Pear-shaped handle','Works on the wheel-and-axle and wedge principles']::text[], array['Coupland chisel','Periosteal elevator']::text[], array['Cryer''s elevator','Periosteal elevator','Warwick James'' elevator']::text[], 'Never use an adjacent tooth as a fulcrum unless it is also being extracted.', array['Luxation of teeth and roots before forceps extraction','Concave surface faces the tooth to be extracted']::text[], 1),
(12, 3, null, 'instrument', 'Cryer''s elevator (East–West)', 'spotters/i-cryer.svg', null, array['Triangular, pointed blade at right angles to the shank','Used in pairs – right and left','Wheel-and-axle principle']::text[], array['Winter''s cross-bar elevator']::text[], array['Straight elevator','Warwick James'' elevator','Coupland chisel']::text[], 'Also called the triangular or East–West elevator.', array['Removal of a retained root when the other root of a molar has been extracted','Inserted into the empty socket, engages the inter-radicular bone']::text[], 2),
(13, 4, null, 'instrument', 'Amalgam carrier', 'spotters/i-amalgam-carrier.svg', null, array['Hollow barrel at the working end','Spring-loaded plunger with lever','Double-ended in some designs (small and large barrel)']::text[], array[]::text[], array['Amalgam condenser','Burnisher','Composite gun']::text[], 'Do not leave amalgam in the barrel – it sets and jams the plunger.', array['Carries triturated amalgam to the prepared cavity in increments']::text[], 1),
(14, 1, null, 'specimen', 'Compound odontome', 'spotters/s-compound-odontome.svg', null, array['Multiple small, tooth-like structures (denticles)','Enamel, dentine, cementum and pulp in normal relationship','Usually anterior maxilla; may block eruption of a permanent tooth']::text[], array['Complex odontome (disorganised mass, posterior mandible)']::text[], array['Complex odontome','Cementoblastoma','Supernumerary tooth']::text[], 'Compound = anterior maxilla, tooth-like; complex = posterior mandible, amorphous mass.', array[]::text[], 2)
insert into public.mcq_questions (id, subject, question, options, answer, explanation, is_pyq, is_important, exam) values
(1, 'Dental Anatomy', 'Which is usually the first permanent tooth to erupt in the oral cavity?', array['Maxillary central incisor','Mandibular central incisor','Mandibular first molar','Maxillary first molar']::text[], 2, 'The mandibular first molar erupts at about 6 years, usually just before the mandibular central incisor. It is the first succedaneous-free (non-replacing) permanent tooth.', true, true, 'NEET MDS'),
(2, 'Dental Anatomy', 'Cusp of Carabelli is seen on which cusp of the maxillary first molar?', array['Mesiobuccal','Distobuccal','Mesiopalatal','Distopalatal']::text[], 2, 'The cusp of Carabelli is an accessory cusp on the palatal surface of the mesiopalatal (mesiolingual) cusp of the maxillary first molar.', true, true, 'NEET MDS'),
(3, 'Dental Anatomy', 'The longest root in the permanent dentition is seen in:', array['Maxillary central incisor','Maxillary canine','Mandibular canine','Maxillary first premolar']::text[], 1, 'The maxillary canine has the longest root of all teeth, making it a key abutment and the ''cornerstone'' of the arch.', true, false, 'NEET MDS'),
(4, 'Dental Anatomy', 'A ''Y''-shaped occlusal groove pattern is characteristic of:', array['Two-cusp mandibular second premolar','Three-cusp mandibular second premolar','Maxillary first premolar','Mandibular first premolar']::text[], 1, 'The three-cusp (one buccal, two lingual) form of the mandibular second premolar shows a Y-shaped groove; the two-cusp form shows an H or U pattern.', false, true, 'NEET MDS'),
(5, 'Dental Anatomy', 'Which permanent tooth commonly has two roots (buccal and palatal)?', array['Maxillary second premolar','Maxillary first premolar','Mandibular first premolar','Maxillary canine']::text[], 1, 'The maxillary first premolar usually has two roots – buccal and palatal. The second premolar usually has one.', true, false, 'NEET MDS'),
(6, 'Anatomy', 'Muscles of mastication are supplied by:', array['Facial nerve','Maxillary nerve','Mandibular nerve','Hypoglossal nerve']::text[], 2, 'All four muscles of mastication (masseter, temporalis, medial and lateral pterygoid) are supplied by the mandibular division of the trigeminal nerve (V3).', true, true, 'NEET MDS'),
(7, 'Anatomy', 'Which muscle of the tongue is NOT supplied by the hypoglossal nerve?', array['Genioglossus','Hyoglossus','Styloglossus','Palatoglossus']::text[], 3, 'Palatoglossus is supplied by the vagus nerve via the pharyngeal plexus. All other tongue muscles are supplied by the hypoglossal nerve.', true, true, 'NEET MDS'),
(8, 'Anatomy', 'The parotid (Stensen''s) duct opens opposite the:', array['Maxillary first premolar','Maxillary second molar','Mandibular first molar','Maxillary canine']::text[], 1, 'Stensen''s duct pierces the buccinator and opens into the vestibule opposite the crown of the maxillary second molar.', true, false, 'NEET MDS'),
(9, 'Anatomy', 'General sensation from the anterior two-thirds of the tongue is carried by the:', array['Chorda tympani','Glossopharyngeal nerve','Lingual nerve','Hypoglossal nerve']::text[], 2, 'The lingual nerve (V3) carries general sensation from the anterior 2/3. Taste from that area travels in the chorda tympani (VII).', false, true, 'NEET MDS'),
(10, 'Anatomy', 'Which muscle is chiefly responsible for protrusion and depression (opening) of the mandible?', array['Masseter','Temporalis','Medial pterygoid','Lateral pterygoid']::text[], 3, 'The lateral pterygoid pulls the condyle and disc forward, so it protrudes the mandible and helps open the mouth. The other three muscles close it.', true, false, 'NEET MDS'),
(11, 'Physiology', 'Which salivary gland contributes most to unstimulated (resting) saliva?', array['Parotid','Submandibular','Sublingual','Minor salivary glands']::text[], 1, 'At rest the submandibular gland produces about 65–70% of saliva. On stimulation, the parotid''s share rises sharply.', true, true, 'NEET MDS'),
(12, 'Physiology', 'The normal pacemaker of the heart is the:', array['AV node','SA node','Bundle of His','Purkinje fibres']::text[], 1, 'The SA node has the fastest intrinsic rate of depolarisation, so it sets the heart rate.', true, false, 'NEET MDS'),
(13, 'Physiology', 'Which hormone raises serum calcium levels?', array['Calcitonin','Parathormone','Insulin','Glucagon']::text[], 1, 'Parathormone raises serum calcium by increasing bone resorption, renal calcium reabsorption and calcitriol formation. Calcitonin lowers calcium.', false, true, 'NEET MDS'),
(14, 'Physiology', 'Bleeding time mainly assesses:', array['Intrinsic pathway','Extrinsic pathway','Platelet function','Fibrinolysis']::text[], 2, 'Bleeding time reflects platelet number and function (primary haemostasis). PT tests the extrinsic pathway and aPTT the intrinsic pathway.', true, true, 'NEET MDS'),
(15, 'Physiology', 'The vitamin K–dependent clotting factors are:', array['I, II, V, VIII','II, VII, IX, X','III, V, VIII, XI','VIII, IX, XI, XII']::text[], 1, 'Factors II, VII, IX and X (plus proteins C and S) need vitamin K for gamma-carboxylation. Warfarin antagonises this step.', true, true, 'NEET MDS'),
(16, 'Biochemistry', 'Vitamin C deficiency impairs collagen synthesis by affecting:', array['Glycosylation of lysine','Hydroxylation of proline and lysine','Cleavage of procollagen','Cross-linking by lysyl oxidase']::text[], 1, 'Ascorbic acid is a cofactor for prolyl and lysyl hydroxylases. Without it, collagen is unstable, which causes scurvy with bleeding, swollen gums.', true, true, 'NEET MDS'),
(17, 'Biochemistry', 'The most abundant amino acid in collagen is:', array['Proline','Hydroxyproline','Glycine','Lysine']::text[], 2, 'Glycine occupies every third position (Gly-X-Y), which allows the tight triple-helix packing.', true, false, 'NEET MDS'),
(18, 'Pathology', 'Reed–Sternberg cells are characteristic of:', array['Non-Hodgkin lymphoma','Hodgkin lymphoma','Multiple myeloma','Burkitt lymphoma']::text[], 1, 'Reed–Sternberg cells are large ''owl-eye'' cells and are the hallmark of Hodgkin lymphoma.', true, false, 'NEET MDS'),
(19, 'Pathology', 'The most common malignant tumour of the oral cavity is:', array['Adenocarcinoma','Squamous cell carcinoma','Basal cell carcinoma','Melanoma']::text[], 1, 'Over 90% of oral cancers are squamous cell carcinomas.', true, true, 'NEET MDS'),
(20, 'Pathology', '''Starry sky'' appearance on histology is seen in:', array['Hodgkin lymphoma','Burkitt lymphoma','Multiple myeloma','CLL']::text[], 1, 'In Burkitt lymphoma, tingible-body macrophages scattered among sheets of tumour cells give the ''starry sky'' pattern.', false, true, 'NEET MDS'),
(21, 'Microbiology', 'The organism chiefly associated with the initiation of dental caries is:', array['Lactobacillus acidophilus','Streptococcus mutans','Actinomyces viscosus','Porphyromonas gingivalis']::text[], 1, 'S. mutans initiates enamel caries. Lactobacilli are linked more with progression of the lesion.', true, true, 'NEET MDS'),
(22, 'Microbiology', 'Standard autoclave conditions are:', array['100 °C for 30 min','121 °C at 15 psi for 15 min','160 °C for 1 h','134 °C at 5 psi for 1 min']::text[], 1, 'Moist heat at 121 °C and 15 psi for 15 minutes is the standard cycle. The flash cycle is 134 °C at about 30 psi for 3 minutes.', true, true, 'NEET MDS'),
(23, 'Microbiology', 'Localized aggressive periodontitis is most strongly associated with:', array['Treponema denticola','Aggregatibacter actinomycetemcomitans','Fusobacterium nucleatum','Streptococcus sanguinis']::text[], 1, 'A. actinomycetemcomitans (which produces leukotoxin) is the key pathogen in localized aggressive periodontitis.', true, true, 'NEET MDS'),
(24, 'Microbiology', 'Koplik''s spots are seen in:', array['Mumps','Measles','Rubella','Chickenpox']::text[], 1, 'Koplik''s spots are bluish-white spots on the buccal mucosa that appear in the prodrome of measles (rubeola).', true, false, 'NEET MDS'),
(25, 'Pharmacology', 'The drug of choice for anaphylactic shock is:', array['Hydrocortisone IV','Adrenaline IM','Chlorpheniramine','Atropine']::text[], 1, 'Adrenaline 1:1000 at 0.5 mg IM (adult) is first-line. Antihistamines and steroids are only adjuncts.', true, true, 'NEET MDS'),
(26, 'Pharmacology', 'The maximum recommended dose of lignocaine WITH adrenaline is:', array['2 mg/kg','4.4 mg/kg','7 mg/kg','10 mg/kg']::text[], 2, 'About 7 mg/kg with adrenaline (500 mg max), and about 4.4 mg/kg without it (300 mg max). The vasoconstrictor slows absorption.', true, true, 'NEET MDS'),
(27, 'Pharmacology', 'The antidote for heparin overdose is:', array['Vitamin K','Protamine sulfate','Fresh frozen plasma','Tranexamic acid']::text[], 1, 'Protamine sulfate neutralises heparin. Vitamin K reverses warfarin.', true, false, 'NEET MDS'),
(28, 'Pharmacology', 'Which local anaesthetic belongs to the ester group?', array['Lignocaine','Bupivacaine','Procaine','Articaine']::text[], 2, 'Procaine is an ester. The others are amides; a quick check is that amide names contain two ''i''s (e.g. l-i-gnoca-i-ne). Articaine is an amide with an ester side chain.', false, true, 'NEET MDS'),
(29, 'Pharmacology', 'Gingival enlargement is a well-known side effect of:', array['Aspirin','Phenytoin','Paracetamol','Amoxicillin']::text[], 1, 'Phenytoin, cyclosporine and calcium-channel blockers (e.g. nifedipine) cause drug-induced gingival overgrowth.', true, true, 'NEET MDS'),
(30, 'Dental Materials', 'The gamma-2 phase in dental amalgam is:', array['Ag3Sn','Ag2Hg3','Sn7-8Hg','Cu6Sn5']::text[], 2, 'Gamma-2 (Sn–Hg) is the weakest and most corrosion-prone phase. High-copper alloys eliminate it by forming Cu6Sn5 instead.', true, true, 'NEET MDS'),
(31, 'Dental Materials', 'Which restorative material has a coefficient of thermal expansion closest to tooth structure?', array['Amalgam','Composite resin','Glass ionomer cement','Gold alloy']::text[], 2, 'GIC''s coefficient of thermal expansion is close to that of dentine, which helps it seal well.', true, true, 'NEET MDS'),
(32, 'Dental Materials', 'Die stone with high strength and low setting expansion is ADA:', array['Type I','Type II','Type III','Type IV']::text[], 3, 'Type IV (die stone, high strength, low expansion) is used for dies. Type V has high strength with high expansion.', true, false, 'NEET MDS'),
(33, 'Dental Materials', 'The most hydrophilic elastomeric impression material is:', array['Polysulfide','Condensation silicone','Addition silicone','Polyether']::text[], 3, 'Polyether is inherently hydrophilic, but it also absorbs water, so it must not be stored wet.', true, true, 'NEET MDS'),
(34, 'Dental Materials', 'The liquid of zinc phosphate cement is mainly:', array['Polyacrylic acid','Eugenol','Phosphoric acid','Acetic acid']::text[], 2, 'It is buffered phosphoric acid (with Al and Zn salts). Its low initial pH can irritate the pulp.', true, false, 'NEET MDS'),
(35, 'Oral Pathology', 'The most common odontogenic cyst is the:', array['Dentigerous cyst','Radicular cyst','Odontogenic keratocyst','Lateral periodontal cyst']::text[], 1, 'The radicular (periapical) cyst is the most common odontogenic cyst. The dentigerous cyst is the most common developmental one.', true, true, 'NEET MDS'),
(36, 'Oral Pathology', 'A multilocular ''soap-bubble'' radiolucency in the posterior mandible of an adult most likely suggests:', array['Radicular cyst','Ameloblastoma','Odontoma','Cementoblastoma']::text[], 1, 'Ameloblastoma typically shows a multilocular soap-bubble or honeycomb pattern in the molar–ramus region, often with root resorption.', true, true, 'NEET MDS'),
(37, 'Oral Pathology', 'Multiple odontogenic keratocysts are a feature of:', array['Gardner syndrome','Gorlin–Goltz syndrome','Peutz–Jeghers syndrome','Cherubism']::text[], 1, 'Gorlin–Goltz (nevoid basal cell carcinoma) syndrome: multiple OKCs, basal cell carcinomas, bifid ribs, and calcified falx cerebri.', true, true, 'NEET MDS'),
(38, 'Oral Pathology', '''Ghost cells'' are characteristic of:', array['Calcifying odontogenic cyst','Adenomatoid odontogenic tumour','Pindborg tumour','Odontogenic myxoma']::text[], 0, 'Ghost cells are anucleate, swollen keratinised epithelial cells. They are the hallmark of the calcifying odontogenic cyst (Gorlin cyst).', true, false, 'NEET MDS'),
(39, 'Oral Pathology', 'Liesegang ring calcifications and amyloid are seen in:', array['Ameloblastoma','Calcifying epithelial odontogenic tumour','AOT','Ameloblastic fibroma']::text[], 1, 'CEOT (Pindborg tumour) shows amyloid-like material with concentric Liesegang ring calcifications.', false, true, 'NEET MDS'),
(40, 'Oral Medicine & Radiology', 'Hutchinson''s incisors are seen in:', array['Ectodermal dysplasia','Congenital syphilis','Fluorosis','Amelogenesis imperfecta']::text[], 1, 'Hutchinson''s triad = notched screwdriver-shaped incisors, interstitial keratitis and VIII-nerve deafness. Mulberry molars are also seen.', true, true, 'NEET MDS'),
(41, 'Oral Medicine & Radiology', 'Which cells are the most radiosensitive?', array['Neurons','Muscle cells','Lymphocytes','Osteocytes']::text[], 2, 'Small lymphocytes are the most radiosensitive cells. Mature neurons and muscle cells are among the most radioresistant.', true, false, 'NEET MDS'),
(42, 'Oral Medicine & Radiology', 'A ''sunray'' or ''sunburst'' radiographic appearance is classically seen in:', array['Ewing sarcoma','Osteosarcoma','Fibrous dysplasia','Paget disease']::text[], 1, 'Spicules of tumour bone radiating outward give the sunburst appearance in osteosarcoma. Ewing sarcoma gives ''onion-peel''.', true, true, 'NEET MDS'),
(43, 'Oral Medicine & Radiology', '''Ground-glass'' appearance of the jaw is typical of:', array['Fibrous dysplasia','Osteomyelitis','Cherubism','Ameloblastoma']::text[], 0, 'Fibrous dysplasia shows a ground-glass (orange-peel) appearance with poorly defined margins that blend into normal bone.', false, true, 'NEET MDS'),
(44, 'Orthodontics', 'Angle''s Class II Division 2 malocclusion shows:', array['Proclined maxillary incisors','Retroclined maxillary central incisors','Anterior open bite','Mesial molar relation']::text[], 1, 'Div 2 shows retroclined maxillary centrals, often with proclined laterals and a deep bite. Div 1 shows proclined incisors.', true, true, 'NEET MDS'),
(45, 'Orthodontics', 'The leeway space in the mandibular arch is approximately (per side):', array['0.9 mm','1.7 mm','2.5 mm','3.4 mm']::text[], 1, 'Leeway space is about 0.9 mm per side in the maxilla and 1.7 mm per side in the mandible.', true, true, 'NEET MDS'),
(46, 'Orthodontics', 'The Activator (functional appliance) was introduced by:', array['Frankel','Andresen','Clark','Bimler']::text[], 1, 'Viggo Andresen developed the activator (Norwegian system). Clark designed the Twin Block, and Frankel the Function Regulator.', true, false, 'NEET MDS'),
(47, 'Orthodontics', 'The Twin Block appliance was developed by:', array['William Clark','Rolf Frankel','Herbert Balters','Pierre Robin']::text[], 0, 'William J. Clark introduced the Twin Block in 1977. Balters designed the Bionator.', false, true, 'NEET MDS'),
(48, 'Pedodontics', 'Buckley''s formocresol contains formaldehyde at:', array['5%','19%','35%','50%']::text[], 1, 'Buckley''s formocresol is 19% formaldehyde, 35% cresol and 15% glycerine in water. A 1:5 dilution is commonly used.', true, true, 'NEET MDS'),
(49, 'Pedodontics', 'In nursing bottle (early childhood) caries, the teeth typically spared are the:', array['Maxillary incisors','Mandibular incisors','Maxillary first molars','Maxillary canines']::text[], 1, 'Mandibular incisors are protected by the tongue and by saliva from the sublingual and submandibular ducts.', true, true, 'NEET MDS'),
(50, 'Pedodontics', 'Duraphat fluoride varnish contains:', array['2% NaF','5% NaF (22,600 ppm F)','1.23% APF','8% SnF2']::text[], 1, 'Duraphat is 5% sodium fluoride, which equals 22,600 ppm fluoride.', true, false, 'NEET MDS'),
(51, 'Periodontics', 'A probe with a 0.5 mm ball tip and a colour band at 3.5–5.5 mm is the:', array['Williams probe','Nabers probe','WHO (CPITN) probe','Marquis probe']::text[], 2, 'The WHO/CPITN probe has a 0.5 mm ball end with markings at 3.5, 5.5, 8.5 and 11.5 mm.', true, true, 'NEET MDS'),
(52, 'Periodontics', 'Gracey curette 11/12 is designed for:', array['Anterior teeth','Mesial surfaces of posterior teeth','Distal surfaces of posterior teeth','Facial and lingual of premolars']::text[], 1, '11/12 is for mesial surfaces of posterior teeth and 13/14 for distal surfaces. 1/2 and 3/4 are for anteriors.', true, true, 'NEET MDS'),
(53, 'Periodontics', 'According to Gargiulo, the average biologic width is about:', array['1.07 mm','2.04 mm','3.00 mm','0.69 mm']::text[], 1, 'Biologic width ≈ 0.97 mm epithelial attachment + 1.07 mm connective tissue attachment = 2.04 mm. Sulcus depth is about 0.69 mm.', true, true, 'NEET MDS'),
(54, 'Periodontics', 'The Plaque Index was introduced by:', array['Löe and Silness','Silness and Löe','Greene and Vermillion','Russell']::text[], 1, 'Plaque Index – Silness & Löe (1964). Gingival Index – Löe & Silness (1963). OHI-S – Greene & Vermillion.', true, false, 'NEET MDS'),
(55, 'Prosthodontics', 'Kennedy Class I partially edentulous arch has:', array['Unilateral distal extension','Bilateral distal extension','Unilateral bounded space','Single anterior space crossing midline']::text[], 1, 'Class I = bilateral posterior edentulous areas; Class II = unilateral distal extension; Class III = unilateral bounded; Class IV = a single anterior area crossing the midline.', true, true, 'NEET MDS'),
(56, 'Prosthodontics', 'The posterior palatal seal of a maxillary denture is placed at:', array['Rugae area','Junction of hard and soft palate (vibrating line)','Incisive papilla','Fovea palatini only']::text[], 1, 'The posterior palatal seal lies between the anterior and posterior vibrating lines, at the junction of hard and soft palate.', true, true, 'NEET MDS'),
(57, 'Prosthodontics', 'A Gothic arch (needle-point) tracing is used to record:', array['Vertical dimension','Centric relation','Protrusive relation only','Face-bow transfer']::text[], 1, 'The apex of the arrow-point tracing marks centric relation, a horizontal jaw relation.', true, false, 'NEET MDS'),
(58, 'Prosthodontics', 'The organism most commonly implicated in denture stomatitis is:', array['Staphylococcus aureus','Candida albicans','Streptococcus mutans','Herpes simplex']::text[], 1, 'Candida albicans, helped by poor denture hygiene and continuous wearing, causes denture stomatitis.', false, true, 'NEET MDS'),
(59, 'Conservative & Endo', 'G.V. Black Class V cavities involve:', array['Pits and fissures','Proximal surfaces of posterior teeth','Gingival third of facial or lingual surfaces','Incisal angle of anterior teeth']::text[], 2, 'Class V = cervical (gingival third) lesions on facial or lingual surfaces.', true, false, 'NEET MDS'),
(60, 'Conservative & Endo', 'The approximate pH of calcium hydroxide is:', array['7.0','9.0','12.5','14.0']::text[], 2, 'Its high pH (about 12.5) makes it antibacterial and helps stimulate dentine bridge formation.', true, true, 'NEET MDS'),
(61, 'Conservative & Endo', 'The material of choice for repairing root perforations is:', array['Zinc oxide eugenol','Calcium hydroxide','MTA','Gutta-percha']::text[], 2, 'MTA is biocompatible, seals well even when moist, and induces hard-tissue formation. Biodentine is an alternative.', true, true, 'NEET MDS'),
(62, 'Conservative & Endo', 'Ideally, root canal working length should end at:', array['Radiographic apex','Apical constriction (minor diameter)','Major diameter (apical foramen)','2 mm beyond the apex']::text[], 1, 'The apical constriction (CDJ region) is about 0.5–1 mm short of the radiographic apex. It is the narrowest point and the ideal end point.', true, true, 'NEET MDS'),
(63, 'Conservative & Endo', 'Weine''s classification is used to describe:', array['Root canal configurations','Cavity designs','Pulp diseases','Crown fractures']::text[], 0, 'Weine classified canal configurations (Types I–IV). Vertucci''s classification has 8 types.', false, true, 'NEET MDS'),
(64, 'Oral Surgery', 'Le Fort I fracture is also known as:', array['Pyramidal fracture','Craniofacial dysjunction','Guerin''s fracture','Tripod fracture']::text[], 2, 'Le Fort I is a horizontal (Guerin''s) fracture above the apices of the teeth. Le Fort II is pyramidal and Le Fort III is craniofacial dysjunction.', true, true, 'NEET MDS'),
(65, 'Oral Surgery', 'Pell and Gregory classification of impacted mandibular third molars is based on:', array['Angulation only','Relationship to ramus and depth relative to occlusal plane','Root morphology','Relation to the inferior alveolar canal']::text[], 1, 'Class I–III describes the relation to the anterior ramus; position A–C describes depth relative to the occlusal plane. Winter''s classification is based on angulation.', true, true, 'NEET MDS'),
(66, 'Oral Surgery', 'Winter''s WAR lines are used in assessing:', array['TMJ ankylosis','Impacted mandibular third molars','Cleft palate','Orbital fractures']::text[], 1, 'White, Amber and Red lines on a radiograph estimate the depth and difficulty of a third molar impaction.', true, false, 'NEET MDS'),
(67, 'Oral Surgery', 'Dry socket (alveolar osteitis) most commonly follows extraction of:', array['Maxillary incisors','Mandibular third molar','Maxillary first molar','Mandibular premolars']::text[], 1, 'It is most common after mandibular third molar surgery, typically appearing 2–4 days after extraction.', false, true, 'NEET MDS'),
(68, 'Public Health Dentistry', 'The DMF index was introduced by:', array['Dean','Klein, Palmer and Knutson','Russell','Greene and Vermillion']::text[], 1, 'Klein, Palmer and Knutson introduced the DMF index in 1938.', true, true, 'NEET MDS'),
(69, 'Public Health Dentistry', 'Dental fluorosis is classically assessed by:', array['Russell''s index','Dean''s fluorosis index','Ramfjord index','CPITN']::text[], 1, 'Dean''s index (1934, modified 1942) is the classic fluorosis index. TF and TSIF are other indices.', true, true, 'NEET MDS'),
(70, 'Public Health Dentistry', 'The main mechanism by which fluoride prevents caries is:', array['Systemic incorporation before eruption','Topical action that enhances remineralisation','Killing all oral bacteria','Increasing salivary flow']::text[], 1, 'The current concept is that fluoride works mainly topically after eruption: it enhances remineralisation, inhibits demineralisation and affects bacterial enzymes.', false, true, 'NEET MDS'),
(1001, 'Medical emergencies', 'A 45-year-old (70 kg) develops widespread urticaria, wheeze and a falling blood pressure two minutes after a rubber-dam is placed. What is the first drug to give?', array['Hydrocortisone 200 mg IV','Adrenaline 0.5 mg (0.5 mL of 1:1000) IM into the anterolateral thigh','Promethazine 25 mg orally','Salbutamol 4 puffs via spacer only']::text[], 1, 'Anaphylaxis (likely latex): adrenaline IM 0.01 mg/kg, max 0.5 mg, into the anterolateral thigh, repeated every 5 minutes if needed. Call an ambulance and lie the patient flat. Antihistamines and steroids are not first-line.', false, true, 'ADC'),
(1002, 'Medical emergencies', 'A patient with known angina develops central chest pain while you are preparing a crown. He is alert and his blood pressure is normal. What do you give first?', array['Aspirin 300 mg and wait 15 minutes','Glyceryl trinitrate 400 microgram spray under the tongue','Adrenaline 0.5 mg IM','Midazolam buccal']::text[], 1, 'Stop treatment, sit the patient up and give sublingual GTN. If pain persists after the first dose, call an ambulance; aspirin 300 mg is given for suspected acute coronary syndrome if not contraindicated.', false, true, 'ADC'),
(1003, 'Medical emergencies', 'A patient with type 1 diabetes skipped lunch and becomes sweaty, shaky and confused but can still swallow. What is the most appropriate management?', array['Glucagon 1 mg IM immediately','15–20 g of fast-acting oral glucose, then recheck','Insulin from the patient''s pen','Lie flat and give oxygen only']::text[], 1, 'Conscious hypoglycaemia: oral fast-acting glucose (e.g. glucose tablets, juice), recheck after 10–15 minutes, then a longer-acting carbohydrate. Glucagon IM is for a patient who cannot swallow safely.', false, true, 'ADC'),
(1004, 'Medical emergencies', 'A young patient faints in the chair before an injection. Pulse is slow but present and breathing is normal. What is the first step?', array['Sit the patient upright','Lay the patient flat and raise the legs','Give adrenaline IM','Start CPR']::text[], 1, 'Vasovagal syncope: lay flat, raise the legs to improve venous return, loosen tight clothing and give oxygen. Recovery is usually rapid; if not, reassess for other causes.', false, false, 'ADC'),
(1005, 'Therapeutics', 'A patient taking warfarin (INR 2.4 measured yesterday) needs a simple extraction of a lower first molar. What is the best approach?', array['Stop warfarin for 5 days before the extraction','Proceed without stopping warfarin, using local haemostatic measures','Switch to aspirin for a week','Refer to hospital for vitamin K']::text[], 1, 'For simple extractions with a stable INR in the therapeutic range (generally ≤ 3), continue warfarin and use local measures: atraumatic technique, haemostatic dressing, sutures and tranexamic acid mouthwash. Stopping warfarin risks thromboembolism.', false, true, 'ADC'),
(1006, 'Therapeutics', 'Which patient needs antibiotic prophylaxis against infective endocarditis before a dental extraction?', array['Mitral valve prolapse without regurgitation','A patient with a prosthetic heart valve','Controlled hypertension','A coronary stent placed 2 years ago']::text[], 1, 'Prophylaxis is limited to highest-risk cardiac conditions, such as prosthetic valves, previous infective endocarditis, some congenital heart disease and rheumatic heart disease in Aboriginal and Torres Strait Islander patients. Stents, hypertension and MVP alone do not qualify.', false, true, 'ADC'),
(1007, 'Therapeutics', 'Following an endocarditis-risk assessment, which oral regimen is standard prophylaxis for an adult with no penicillin allergy?', array['Amoxicillin 2 g orally, 60 minutes before the procedure','Amoxicillin 500 mg three times daily for 5 days after','Metronidazole 400 mg 1 hour before','Doxycycline 100 mg the night before']::text[], 0, 'A single 2 g oral dose of amoxicillin about an hour before the procedure. Antibiotics are not continued afterwards for prophylaxis.', false, false, 'ADC'),
(1008, 'Therapeutics', 'A 68-year-old receiving IV zoledronic acid for metastatic breast cancer needs a lower molar removed. What is the best approach?', array['Extract and prescribe antibiotics for a week','Avoid extraction where possible; consider root canal treatment and crown removal (decoronation) with specialist advice','Stop zoledronic acid for one week and extract','There is no added risk; extract routinely']::text[], 1, 'High-dose IV antiresorptives for cancer carry the highest risk of medication-related osteonecrosis of the jaw. Prefer non-surgical options and seek specialist advice. A short drug holiday does not remove the risk from bisphosphonates.', false, false, 'ADC'),
(1009, 'Ethics & law', 'A dentist forms a reasonable belief that a colleague has repeatedly treated patients while intoxicated with alcohol. What must the dentist do?', array['Speak to the colleague privately and take no further action','Make a mandatory notification to AHPRA','Report only if a patient complains','Tell the practice owner and let them decide']::text[], 1, 'Practising while intoxicated by alcohol or drugs is notifiable conduct under the National Law; registered practitioners must notify AHPRA when they form a reasonable belief.', false, true, 'ADC'),
(1010, 'Ethics & law', 'Which Australian High Court case established that a practitioner must warn patients of material risks of treatment?', array['Rogers v Whitaker (1992)','Bolam v Friern Hospital (1957)','Gillick v West Norfolk (1985)','Montgomery v Lanarkshire (2015)']::text[], 0, 'Rogers v Whitaker: a risk is material if a reasonable person in the patient''s position would attach significance to it, or if the practitioner knows this particular patient would. Bolam, Gillick and Montgomery are UK cases.', false, true, 'ADC'),
(1011, 'Ethics & law', 'A 15-year-old attends alone and wants a filling. She clearly understands the procedure, risks and alternatives. Can she consent?', array['No – only a parent can consent for anyone under 18','Yes – a minor who has sufficient maturity and understanding (a "mature minor") can consent','Only with written permission from the school','Only if the treatment is free']::text[], 1, 'Australian common law (Gillick, adopted in Marion''s case) allows a mature minor to consent when they understand fully what is proposed. Assess and document competence; encourage involving parents where appropriate.', false, false, 'ADC'),
(1012, 'Infection control', 'Under the Spaulding classification, which item must be sterile at the point of use?', array['Mouth mirror used for examination','Surgical extraction forceps','Blood-pressure cuff','Dental chair headrest']::text[], 1, 'Critical items that penetrate soft tissue or bone must be sterile. Semi-critical items such as mirrors contact mucosa only and need sterilisation where possible (or high-level disinfection). Non-critical items touch intact skin.', false, true, 'ADC'),
(1013, 'Infection control', 'Your hands are not visibly soiled and you are about to touch a new patient. What is the recommended hand hygiene?', array['Alcohol-based hand rub','Surgical scrub with chlorhexidine for 3 minutes','Rinse with water only','Put gloves on over unwashed hands']::text[], 0, 'Alcohol-based hand rub is preferred when hands are not visibly soiled ("5 moments" of hand hygiene). Visibly soiled hands need soap and water; surgical scrub is for surgical procedures.', false, false, 'ADC'),
(1014, 'Infection control', 'A dental assistant sustains a needlestick injury from a used LA needle. What is the immediate first step?', array['Squeeze the wound hard and apply bleach','Wash the area with soap and running water, then report and arrange risk assessment','Finish the patient''s treatment first','Start antiretroviral medication immediately without assessment']::text[], 1, 'First aid: wash with soap and water (do not scrub or use bleach), report the incident, assess the source patient''s risk with consent, and arrange medical follow-up within hours in case post-exposure prophylaxis is needed.', false, false, 'ADC'),
(1015, 'Radiology', 'Which change reduces patient radiation dose most for intraoral radiographs?', array['Round collimation with a longer exposure','Rectangular collimation','Using a lead apron only','Using D-speed film']::text[], 1, 'Rectangular collimation greatly reduces the irradiated area compared with round collimation. Fast receptors (F-speed or digital) also reduce dose; routine lead aprons add little benefit for intraoral imaging.', false, false, 'ADC'),
(1016, 'Paediatric dentistry', 'A 10-year-old''s permanent upper central incisor was avulsed 20 minutes ago. Which storage medium should the parent use if the tooth cannot be replanted immediately?', array['Tap water','Cold milk','Dry tissue paper','Alcohol-based mouthwash']::text[], 1, 'Milk preserves periodontal ligament cell viability far better than water or dry storage (Hank''s solution is better still if available). Replant as soon as possible and splint flexibly for about 2 weeks.', false, true, 'ADC'),
(1017, 'Paediatric dentistry', 'A 3-year-old has avulsed a primary upper central incisor. What is the correct management?', array['Replant and splint for 2 weeks','Do not replant; check for injury to soft tissues and the developing permanent tooth','Replant without a splint','Place a space maintainer immediately']::text[], 1, 'Avulsed primary teeth are not replanted because of the risk to the developing successor. Advise on soft diet, hygiene and follow-up.', false, false, 'ADC'),
(1018, 'Paediatric dentistry', 'Under Australian guidance for fluoride use, what is advised for a 12-month-old with low caries risk?', array['Brush with a smear of adult toothpaste twice daily','Clean teeth with a soft brush but no toothpaste unless a professional advises otherwise','Fluoride supplements daily','Professional fluoride varnish every month']::text[], 1, 'Children under 18 months should not use toothpaste unless advised by a health professional. From 18 months to 5 years, a pea-sized amount of low-strength fluoride toothpaste is used.', false, false, 'ADC'),
(1019, 'Endodontics', 'A lower molar has sharp pain to cold that lingers for over a minute and wakes the patient at night. The tooth is not tender to percussion. What is the pulpal diagnosis?', array['Reversible pulpitis','Symptomatic irreversible pulpitis','Pulp necrosis','Normal pulp']::text[], 1, 'Lingering pain after a thermal stimulus plus spontaneous night pain indicates symptomatic irreversible pulpitis. Treatment is pulpotomy or pulpectomy and root canal treatment, or extraction.', false, false, 'ADC'),
(1020, 'Periodontics', 'A 45-year-old non-smoker has 6 mm interdental attachment loss, bone loss extending to the middle third of the root, and has lost 2 teeth to periodontitis. What is the 2017 World Workshop stage?', array['Stage I','Stage II','Stage III','Stage IV']::text[], 2, 'Stage III: interdental CAL ≥ 5 mm, bone loss into the middle third or beyond, and tooth loss due to periodontitis of 4 teeth or fewer. Stage IV involves ≥ 5 teeth lost or complex rehabilitation needs.', false, false, 'ADC'),
(1021, 'Oral medicine', 'A 60-year-old smoker has a painless, non-healing ulcer on the lateral tongue for 4 weeks with an indurated margin. What is the next step?', array['Review in 6 months','Prescribe antifungal and review in 2 weeks','Urgent referral for biopsy to exclude squamous cell carcinoma','Reassure – likely a traumatic ulcer']::text[], 2, 'Any ulcer persisting beyond 2–3 weeks after removing likely causes, especially indurated and in a high-risk site and patient, needs urgent specialist referral and biopsy.', false, true, 'ADC'),
(1022, 'Public health', 'Which brief intervention model is recommended for smoking cessation in Australian primary care, including dental practice?', array['Ask, Advise, Help','Refer every smoker to a cardiologist','Only advise patients who ask','Prescribe nicotine replacement to all smokers without assessment']::text[], 0, 'Ask about smoking, Advise to quit, Help by offering referral to Quitline (13 7848) and discussing pharmacotherapy. It takes a few minutes and is effective.', false, false, 'ADC')
